def gb(x: float) -> float:
    return round(float(x) / (1024 ** 3), 2)


def run_cmd(cmd: List[str], check: bool = True, timeout: Optional[float] = None) -> subprocess.CompletedProcess:
    try:
        result = subprocess.run(
            [str(x) for x in cmd],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=timeout,
        )
    except subprocess.TimeoutExpired:
        print('COMMAND TIMEOUT:', ' '.join(map(str, cmd)))
        raise

    if check and result.returncode != 0:
        print('COMMAND:', ' '.join(map(str, cmd)))
        print('STDOUT:\n', result.stdout)
        print('STDERR:\n', result.stderr)
        raise subprocess.CalledProcessError(
            result.returncode,
            cmd,
            output=result.stdout,
            stderr=result.stderr,
        )
    return result


def show_system_status():
    mem = psutil.virtual_memory()
    print('RAM total GB:', gb(mem.total))
    print('RAM available GB:', gb(mem.available))
    print('RAM percent:', mem.percent)

    for label, path in [('FINAL_ROOT', FINAL_ROOT), ('TMP_ROOT', TMP_ROOT), ('RAW_ROOT', RAW_ROOT)]:
        if path.exists():
            usage = shutil.disk_usage(path)
            print(f'\nDisk {label}: {path}')
            print('total GB:', gb(usage.total))
            print('used GB:', gb(usage.used))
            print('free GB:', gb(usage.free))

    print('\nCUDA available:', torch.cuda.is_available())
    if torch.cuda.is_available():
        print('GPU:', torch.cuda.get_device_name(0))
        print('allocated GB:', gb(torch.cuda.memory_allocated()))
        print('reserved GB:', gb(torch.cuda.memory_reserved()))


