def ffmpeg_base_cmd() -> List[str]:
    return [
        'ffmpeg',
        '-nostdin',
        '-hide_banner',
        '-loglevel', 'error',
        '-threads', str(FFMPEG_THREADS_PER_JOB),
    ]


def ffprobe_json(path: Path) -> Dict[str, Any]:
    cmd = [
        'ffprobe',
        '-v', 'error',
        '-show_format',
        '-show_streams',
        '-print_format', 'json',
        str(path),
    ]
    out = run_cmd(cmd, timeout=FFMPEG_TIMEOUT_SEC)
    return json.loads(out.stdout)


def safe_duration_sec(path: Path) -> Optional[float]:
    try:
        info = sf.info(str(path))
        return float(info.frames) / float(info.samplerate)
    except Exception:
        try:
            meta = ffprobe_json(Path(path))
            return float(meta.get('format', {}).get('duration'))
        except Exception:
            return None


def safe_call_id_from_path(path: Path) -> str:
    path = Path(path)
    try:
        rel = path.resolve().relative_to(RAW_ROOT.resolve())
    except Exception:
        rel = path.resolve()

    base = path.parent.name if path.name == 'audio.opus' else path.stem
    safe_base = re.sub(r'[^A-Za-z0-9._-]+', '_', str(base)).strip('_')[:80]
    digest = hashlib.sha1(str(rel).encode('utf-8')).hexdigest()[:12]
    return f'{safe_base}_{digest}'


def target_reached(current_seconds: float, target_seconds: Optional[float]) -> bool:
    return target_seconds is not None and float(current_seconds) >= float(target_seconds)


def flatten_dict(d, parent_key: str = '', sep: str = '.') -> Dict[str, Any]:
    items = {}
    if not isinstance(d, dict):
        return items
    for k, v in d.items():
        new_key = f'{parent_key}{sep}{k}' if parent_key else str(k)
        if isinstance(v, dict):
            items.update(flatten_dict(v, new_key, sep=sep))
        else:
            items[new_key] = v
    return items


def read_metadata_json(audio_path: Path) -> Dict[str, Any]:
    meta_path = Path(audio_path).parent / 'metadata.json'
    if not meta_path.exists():
        return {}
    try:
        with open(meta_path, 'r', encoding='utf-8') as f:
            return flatten_dict(json.load(f))
    except Exception:
        return {}


def find_first_metadata_value(flat_meta: Dict[str, Any], keywords: List[str]) -> Optional[str]:
    for k, v in flat_meta.items():
        lk = str(k).lower()
        if any(keyword.lower() in lk for keyword in keywords):
            if v is not None and str(v).strip() != '':
                return str(v)
    return None


def rms_energy(audio: np.ndarray) -> float:
    if audio is None or len(audio) == 0:
        return 0.0
    arr = np.asarray(audio, dtype=np.float32)
    return float(np.sqrt(np.mean(np.square(arr))))


def clipping_ratio(audio: np.ndarray, threshold: float = 0.99) -> float:
    if audio is None or len(audio) == 0:
        return 0.0
    arr = np.asarray(audio, dtype=np.float32)
    return float(np.mean(np.abs(arr) >= threshold))


