# =========================================================
# FFPROBE, DECODE, AND SAMPLE-ACCURATE SEGMENT WRITING
# =========================================================

def get_first_audio_stream(src_path: Path) -> Dict[str, Any]:
    meta = ffprobe_json(Path(src_path))
    streams = [s for s in meta.get('streams', []) if s.get('codec_type') == 'audio']
    if not streams:
        raise ValueError(f'No audio stream found: {src_path}')

    st = streams[0]
    fmt = meta.get('format', {})
    duration = None
    for value in [st.get('duration'), fmt.get('duration')]:
        if value is not None:
            try:
                duration = float(value)
                break
            except Exception:
                pass

    channels = st.get('channels')
    try:
        channels = int(channels) if channels else 1
    except Exception:
        channels = 1

    sample_rate = st.get('sample_rate')
    try:
        sample_rate = int(sample_rate) if sample_rate else None
    except Exception:
        sample_rate = None

    return {
        'sample_rate': sample_rate,
        'channels': max(1, channels),
        'channel_layout': st.get('channel_layout'),
        'duration_sec': duration,
        'codec_name': st.get('codec_name'),
        'bit_rate': st.get('bit_rate'),
    }


def wav_info(path: Path) -> Dict[str, Any]:
    info = sf.info(str(path))
    return {
        'path': str(path),
        'sample_rate': int(info.samplerate),
        'duration_samples': int(info.frames),
        'duration_sec': float(info.frames) / float(info.samplerate),
        'channels': int(info.channels),
    }


def decode_opus_to_16k_multichannel_wav(src_path: Path, out_dir: Path) -> Dict[str, Any]:
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    out_wav = out_dir / 'full_16k_multichannel.wav'

    try:
        stream_info = get_first_audio_stream(src_path)
        source_channels = max(1, int(stream_info.get('channels') or 1))

        cmd = ffmpeg_base_cmd() + [
            '-y',
            '-i', str(src_path),
            '-vn',
            '-map', '0:a:0',
            '-ar', str(TARGET_SR),
            '-ac', str(source_channels),
            '-c:a', 'pcm_s16le',
            str(out_wav),
        ]
        run_cmd(cmd, timeout=FFMPEG_TIMEOUT_SEC)

        info = wav_info(out_wav)
        channel_infos = []
        for ch_idx in range(int(info['channels'])):
            channel_infos.append({
                'path': str(out_wav),
                'channel': f'ch{ch_idx}',
                'channel_idx': ch_idx,
                'sample_rate': TARGET_SR,
                'duration_samples': int(info['duration_samples']),
                'duration_sec': float(info['duration_sec']),
                'channels_in_file': int(info['channels']),
            })

        return {
            'decode_ok': True,
            'decoded_path': str(out_wav),
            'source_sample_rate': stream_info.get('sample_rate'),
            'channels': int(info['channels']),
            'duration_sec': float(info['duration_sec']),
            'original_container_duration_sec': stream_info.get('duration_sec'),
            'canonical_sample_rate': TARGET_SR,
            'canonical_duration_samples': int(info['duration_samples']),
            'canonical_duration_sec': float(info['duration_sec']),
            'source_codec_name': stream_info.get('codec_name'),
            'source_channel_layout': stream_info.get('channel_layout'),
            'source_bit_rate': stream_info.get('bit_rate'),
            'channel_infos': channel_infos,
            'decode_error': None,
        }
    except Exception as e:
        return {
            'decode_ok': False,
            'decoded_path': str(out_wav),
            'source_sample_rate': None,
            'channels': None,
            'duration_sec': None,
            'original_container_duration_sec': None,
            'canonical_sample_rate': TARGET_SR,
            'canonical_duration_samples': None,
            'canonical_duration_sec': None,
            'source_codec_name': None,
            'source_channel_layout': None,
            'source_bit_rate': None,
            'channel_infos': [],
            'decode_error': repr(e),
        }


def load_wav_16k_multichannel_array(path: Path) -> np.ndarray:
    audio, sr = sf.read(str(path), dtype='float32', always_2d=True)
    if sr != TARGET_SR:
        raise ValueError(f'Expected {TARGET_SR} Hz, got {sr}: {path}')
    return np.asarray(audio, dtype=np.float32)


def save_audio_segment_from_array(
    audio: np.ndarray,
    start_sample: int,
    end_sample: int,
    out_path: Path,
    sr: int = TARGET_SR,
):
    out_path = Path(out_path)
    out_path.parent.mkdir(parents=True, exist_ok=True)

    start_sample = max(0, int(start_sample))
    end_sample = min(len(audio), int(end_sample))
    if end_sample <= start_sample:
        raise ValueError(f'Invalid segment sample range: {start_sample}:{end_sample}')

    segment = np.asarray(audio[start_sample:end_sample], dtype=np.float32)
    sf.write(str(out_path), segment, sr, subtype=SEGMENT_SUBTYPE)

# =========================================================
# SILERO VAD, THREAD-LOCAL FOR PARALLEL AUDIO PREP
# =========================================================

try:
    torch.set_num_threads(1)
    torch.set_num_interop_threads(1)
except Exception:
    pass

_VAD_LOCAL = threading.local()
_VAD_LOAD_LOCK = threading.Lock()


def get_thread_local_vad():
    if not hasattr(_VAD_LOCAL, 'vad_model'):
        with _VAD_LOAD_LOCK:
            local_model, local_utils = torch.hub.load(
                repo_or_dir='snakers4/silero-vad',
                model='silero_vad',
                trust_repo=True,
            )
        local_model.eval()
        local_model.to('cpu')
        _VAD_LOCAL.vad_model = local_model
        _VAD_LOCAL.get_speech_timestamps = local_utils[0]
    return _VAD_LOCAL.vad_model, _VAD_LOCAL.get_speech_timestamps


def merge_vad_intervals(intervals: List[Tuple[float, float]], max_gap_sec: float = MERGE_GAP_SEC) -> List[Tuple[float, float]]:
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [intervals[0]]
    for s, e in intervals[1:]:
        ps, pe = merged[-1]
        if s - pe <= max_gap_sec:
            merged[-1] = (ps, max(pe, e))
        else:
            merged.append((s, e))
    return merged


def interval_overlap_seconds(intervals: List[Tuple[float, float]], start_sec: float, end_sec: float) -> float:
    total = 0.0
    for s, e in intervals:
        total += max(0.0, min(e, end_sec) - max(s, start_sec))
    return float(total)


def run_vad_on_audio_array(audio: np.ndarray, sr: int = TARGET_SR) -> Dict[str, Any]:
    local_vad_model, local_get_speech_timestamps = get_thread_local_vad()
    wav = torch.from_numpy(np.asarray(audio, dtype=np.float32))

    with torch.inference_mode():
        speech_ts = local_get_speech_timestamps(wav, local_vad_model, sampling_rate=sr)

    total_dur = len(wav) / sr
    raw_intervals = [(float(x['start'] / sr), float(x['end'] / sr)) for x in speech_ts]
    merged_intervals = merge_vad_intervals(raw_intervals, max_gap_sec=MERGE_GAP_SEC)

    speech_dur = float(sum(e - s for s, e in merged_intervals))
    silence_dur = max(0.0, total_dur - speech_dur)
    speech_ratio = speech_dur / total_dur if total_dur > 0 else 0.0
    durs = [e - s for s, e in merged_intervals]

    return {
        'vad_total_duration_sec': float(total_dur),
        'vad_speech_duration_sec': speech_dur,
        'vad_silence_duration_sec': float(silence_dur),
        'vad_speech_ratio': float(speech_ratio),
        'vad_num_speech_segments': len(merged_intervals),
        'vad_avg_segment_sec': float(np.mean(durs)) if durs else 0.0,
        'vad_max_segment_sec': float(np.max(durs)) if durs else 0.0,
        'vad_intervals': raw_intervals,
        'vad_merged_intervals': merged_intervals,
    }

print('VAD helper ready. Each audio-prep worker will load its own Silero model.')

# =========================================================
# SMART VAD CHUNKING
# =========================================================

@dataclass
class PauseCandidate:
    split_time: float
    gap_duration: float
    score: float


def find_pause_candidates(intervals_in_block, block_start, target_chunk_sec, min_split_gap_sec=MIN_SPLIT_GAP_SEC):
    candidates = []
    for i in range(len(intervals_in_block) - 1):
        left_end = intervals_in_block[i][1]
        right_start = intervals_in_block[i + 1][0]
        gap = right_start - left_end
        if gap < min_split_gap_sec:
            continue
        split_time = (left_end + right_start) / 2.0
        elapsed = split_time - block_start
        dist_penalty = abs(elapsed - target_chunk_sec)
        score = (2.0 * gap) - (0.35 * dist_penalty)
        candidates.append(PauseCandidate(float(split_time), float(gap), float(score)))
    return candidates


def choose_best_split(candidates, block_start, block_end, min_keep_chunk_sec, max_chunk_sec):
    valid = []
    for c in candidates:
        left_dur = c.split_time - block_start
        right_dur = block_end - c.split_time
        if left_dur < min_keep_chunk_sec or right_dur < min_keep_chunk_sec:
            continue
        adj_score = c.score
        if left_dur > max_chunk_sec:
            adj_score -= 5.0
        if right_dur > max_chunk_sec:
            adj_score -= 5.0
        valid.append((adj_score, c))
    if not valid:
        return None
    valid.sort(key=lambda x: x[0], reverse=True)
    return valid[0][1].split_time


def chunk_long_block(
    block_start,
    block_end,
    raw_intervals_in_block,
    target_chunk_sec=TARGET_CHUNK_SEC,
    min_keep_chunk_sec=MIN_KEEP_CHUNK_SEC,
    max_chunk_sec=MAX_CHUNK_SEC,
    min_split_gap_sec=MIN_SPLIT_GAP_SEC,
    recursion_depth=0,
    max_recursion=MAX_RECURSION,
):
    duration = block_end - block_start
    if duration < min_keep_chunk_sec:
        return []
    if recursion_depth > max_recursion:
        return [(block_start, block_end)]
    if duration <= max_chunk_sec:
        return [(block_start, block_end)]

    candidates = find_pause_candidates(
        raw_intervals_in_block,
        block_start=block_start,
        target_chunk_sec=target_chunk_sec,
        min_split_gap_sec=min_split_gap_sec,
    )
    split_time = choose_best_split(
        candidates,
        block_start=block_start,
        block_end=block_end,
        min_keep_chunk_sec=min_keep_chunk_sec,
        max_chunk_sec=max_chunk_sec,
    )

    if split_time is None:
        split_time = min(block_start + target_chunk_sec, block_end - min_keep_chunk_sec)
        if split_time <= block_start or split_time >= block_end:
            return [(block_start, block_end)]

    left_intervals = [x for x in raw_intervals_in_block if x[1] <= split_time]
    right_intervals = [x for x in raw_intervals_in_block if x[0] >= split_time]
    if not left_intervals:
        left_intervals = [(block_start, split_time)]
    if not right_intervals:
        right_intervals = [(split_time, block_end)]

    return (
        chunk_long_block(block_start, split_time, left_intervals, target_chunk_sec, min_keep_chunk_sec, max_chunk_sec, min_split_gap_sec, recursion_depth + 1, max_recursion)
        + chunk_long_block(split_time, block_end, right_intervals, target_chunk_sec, min_keep_chunk_sec, max_chunk_sec, min_split_gap_sec, recursion_depth + 1, max_recursion)
    )


def build_smart_chunks(
    raw_vad_intervals,
    merge_gap_sec=MERGE_GAP_SEC,
    target_chunk_sec=TARGET_CHUNK_SEC,
    min_keep_chunk_sec=MIN_KEEP_CHUNK_SEC,
    max_chunk_sec=MAX_CHUNK_SEC,
    min_split_gap_sec=MIN_SPLIT_GAP_SEC,
    max_recursion=MAX_RECURSION,
):
    if not raw_vad_intervals:
        return []

    raw_vad_intervals = sorted(raw_vad_intervals, key=lambda x: x[0])
    grouped_blocks = []
    current_group = [raw_vad_intervals[0]]

    for s, e in raw_vad_intervals[1:]:
        prev_end = current_group[-1][1]
        gap = s - prev_end
        if gap <= merge_gap_sec:
            current_group.append((s, e))
        else:
            grouped_blocks.append(current_group)
            current_group = [(s, e)]
    grouped_blocks.append(current_group)

    chunks = []
    for group in grouped_blocks:
        block_start = group[0][0]
        block_end = group[-1][1]
        chunks.extend(
            chunk_long_block(
                block_start=block_start,
                block_end=block_end,
                raw_intervals_in_block=group,
                target_chunk_sec=target_chunk_sec,
                min_keep_chunk_sec=min_keep_chunk_sec,
                max_chunk_sec=max_chunk_sec,
                min_split_gap_sec=min_split_gap_sec,
                recursion_depth=0,
                max_recursion=max_recursion,
            )
        )
    return chunks

# =========================================================
# PROCESS ONE CALL
# =========================================================

def process_one_call(src_path: Path) -> Dict[str, List[Dict[str, Any]]]:
    call_rows = []
    channel_rows = []
    segment_rows = []

    src_path = Path(src_path)
    call_id = safe_call_id_from_path(src_path)
    flat_meta = read_metadata_json(src_path)

    metadata_synthetic_id = find_first_metadata_value(flat_meta, ['syntheticid', 'synthetic_id'])
    metadata_customer_id = find_first_metadata_value(flat_meta, ['customerid', 'customer_id', 'memberid', 'member_id'])
    metadata_agent_id = find_first_metadata_value(flat_meta, ['agentid', 'agent_id', 'agent'])

    try:
        decode_res = decode_opus_to_16k_multichannel_wav(src_path, CHANNELS_DIR / call_id)
        decode_res_for_save = {k: v for k, v in decode_res.items() if k not in {'channel_infos'}}

        call_rows.append({
            'call_id': call_id,
            'src_path': str(src_path),
            'metadata_synthetic_id': metadata_synthetic_id,
            'metadata_customer_id': metadata_customer_id,
            'metadata_agent_id': metadata_agent_id,
            **decode_res_for_save,
        })

        if not decode_res['decode_ok']:
            return {'calls': call_rows, 'channels': channel_rows, 'segments': segment_rows}

        call_duration_samples = int(decode_res['canonical_duration_samples'])
        call_duration_sec = float(decode_res['canonical_duration_sec'])

        if call_duration_sec < MIN_CALL_DURATION_SEC:
            return {'calls': call_rows, 'channels': channel_rows, 'segments': segment_rows}

        decoded_path = Path(decode_res['decoded_path'])
        full_audio = load_wav_16k_multichannel_array(decoded_path)
        duration_samples = int(full_audio.shape[0])
        n_channels = int(full_audio.shape[1])

        if duration_samples != call_duration_samples:
            call_duration_samples = duration_samples
            call_duration_sec = duration_samples / TARGET_SR

        persisted_full_path = None
        if KEEP_FULL_CHANNEL_AUDIO:
            persisted_full_path = FULL_CHANNELS_DIR / call_id / 'full_16k_multichannel.wav'
            persisted_full_path.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(decoded_path, persisted_full_path)

        for channel_idx in range(n_channels):
            channel = f'ch{channel_idx}'
            try:
                audio = np.ascontiguousarray(full_audio[:, channel_idx], dtype=np.float32)
                channel_duration_samples = int(len(audio))
                channel_duration_sec = channel_duration_samples / TARGET_SR

                base_channel = {
                    'call_id': call_id,
                    'channel': channel,
                    'channel_idx': channel_idx,
                    'temp_channel_path': str(decoded_path),
                    'canonical_path': str(persisted_full_path) if persisted_full_path else None,
                    'canonical_path_persisted': bool(persisted_full_path),
                    'canonical_path_type': 'multichannel_16k_wav' if persisted_full_path else None,
                    'metadata_synthetic_id': metadata_synthetic_id,
                    'metadata_customer_id': metadata_customer_id,
                    'metadata_agent_id': metadata_agent_id,
                    'sample_rate': TARGET_SR,
                    'duration_samples': channel_duration_samples,
                    'duration_sec': channel_duration_sec,
                    'call_duration_samples': call_duration_samples,
                    'call_duration_sec': call_duration_sec,
                    'channel_rms': rms_energy(audio),
                    'channel_clip_ratio': clipping_ratio(audio),
                    'channel_ok': True,
                    'channel_error': None,
                }

                vad_res = run_vad_on_audio_array(audio, sr=TARGET_SR)
                channel_rows.append({**base_channel, **vad_res, 'vad_ok': True, 'vad_error': None})

                if SKIP_LOW_SPEECH_CHANNELS and float(vad_res['vad_speech_ratio']) < MIN_CHANNEL_SPEECH_RATIO:
                    continue

                raw_intervals = vad_res['vad_intervals']
                smart_intervals = build_smart_chunks(raw_intervals)

                for idx, (s, e) in enumerate(smart_intervals):
                    start_sample = max(0, int(round(float(s) * TARGET_SR)))
                    end_sample = min(channel_duration_samples, int(round(float(e) * TARGET_SR)))
                    if end_sample <= start_sample:
                        continue

                    segment_duration_samples = end_sample - start_sample
                    duration = segment_duration_samples / TARGET_SR
                    if duration < MIN_KEEP_CHUNK_SEC:
                        continue

                    start_sec = start_sample / TARGET_SR
                    end_sec = end_sample / TARGET_SR
                    seg_path = SEGMENTS_DIR / call_id / channel / f'seg_{idx:05d}.wav'
                    segment_id = f'{call_id}_{channel}_{idx:05d}'

                    try:
                        save_audio_segment_from_array(audio, start_sample, end_sample, seg_path, sr=TARGET_SR)
                        seg_audio = audio[start_sample:end_sample]
                        usable_speech_sec = interval_overlap_seconds(raw_intervals, start_sec, end_sec)
                        segment_speech_ratio = usable_speech_sec / duration if duration > 0 else 0.0

                        segment_rows.append({
                            'call_id': call_id,
                            'channel': channel,
                            'channel_idx': channel_idx,
                            'segment_id': segment_id,
                            'audio_filepath': str(seg_path.resolve()),
                            'sample_rate': TARGET_SR,
                            'start_sample': int(start_sample),
                            'end_sample': int(end_sample),
                            'duration_samples': int(segment_duration_samples),
                            'call_duration_samples': int(call_duration_samples),
                            'call_duration_sec': float(call_duration_sec),
                            'start_sec': round(float(start_sec), 6),
                            'end_sec': round(float(end_sec), 6),
                            'duration': round(float(duration), 6),
                            'usable_speech_sec': float(usable_speech_sec),
                            'segment_speech_ratio': float(segment_speech_ratio),
                            'segment_rms': rms_energy(seg_audio),
                            'segment_clip_ratio': clipping_ratio(seg_audio),
                            'metadata_synthetic_id': metadata_synthetic_id,
                            'metadata_customer_id': metadata_customer_id,
                            'metadata_agent_id': metadata_agent_id,
                            'segment_error': None,
                        })
                    except Exception as e_seg:
                        segment_rows.append({
                            'call_id': call_id,
                            'channel': channel,
                            'channel_idx': channel_idx,
                            'segment_id': segment_id,
                            'audio_filepath': str(seg_path.resolve()),
                            'sample_rate': TARGET_SR,
                            'start_sample': int(start_sample),
                            'end_sample': int(end_sample),
                            'duration_samples': int(segment_duration_samples),
                            'call_duration_samples': int(call_duration_samples),
                            'call_duration_sec': float(call_duration_sec),
                            'start_sec': round(float(start_sec), 6),
                            'end_sec': round(float(end_sec), 6),
                            'duration': round(float(duration), 6),
                            'usable_speech_sec': None,
                            'segment_speech_ratio': None,
                            'segment_rms': None,
                            'segment_clip_ratio': None,
                            'metadata_synthetic_id': metadata_synthetic_id,
                            'metadata_customer_id': metadata_customer_id,
                            'metadata_agent_id': metadata_agent_id,
                            'segment_error': repr(e_seg),
                        })

            except Exception as e_ch:
                channel_rows.append({
                    'call_id': call_id,
                    'channel': channel,
                    'channel_idx': channel_idx,
                    'temp_channel_path': str(decoded_path),
                    'canonical_path': str(persisted_full_path) if persisted_full_path else None,
                    'canonical_path_persisted': bool(persisted_full_path),
                    'canonical_path_type': 'multichannel_16k_wav' if persisted_full_path else None,
                    'metadata_synthetic_id': metadata_synthetic_id,
                    'metadata_customer_id': metadata_customer_id,
                    'metadata_agent_id': metadata_agent_id,
                    'sample_rate': TARGET_SR,
                    'duration_samples': None,
                    'duration_sec': None,
                    'call_duration_samples': decode_res.get('canonical_duration_samples'),
                    'call_duration_sec': decode_res.get('canonical_duration_sec'),
                    'channel_rms': None,
                    'channel_clip_ratio': None,
                    'channel_ok': False,
                    'channel_error': repr(e_ch),
                    'vad_ok': False,
                    'vad_error': repr(e_ch),
                    'vad_intervals': [],
                    'vad_merged_intervals': [],
                })

        del full_audio
        gc.collect()

    finally:
        if not KEEP_TEMP_AUDIO:
            shutil.rmtree(CHANNELS_DIR / call_id, ignore_errors=True)
            shutil.rmtree(DECODED_DIR / call_id, ignore_errors=True)

    return {'calls': call_rows, 'channels': channel_rows, 'segments': segment_rows}

# =========================================================
# AUDIO PREP CHECKPOINT HELPERS
# =========================================================

AUDIO_PREP_BATCH_DIR = CHECKPOINT_DIR / 'audio_prep_batches'
AUDIO_PREP_BATCH_DIR.mkdir(parents=True, exist_ok=True)


def mark_audio_trainable(segments_df: pd.DataFrame) -> pd.DataFrame:
    df = segments_df.copy()
    if len(df) == 0:
        df['is_audio_trainable'] = []
        return df

    df['is_audio_trainable'] = (
        (df['segment_error'].isna())
        & (df['duration'].fillna(0) > 0)
        & (df['duration'].fillna(999999) <= MAX_TRAIN_CHUNK_SEC)
        & (df['usable_speech_sec'].fillna(0) >= MIN_TRAIN_USABLE_SPEECH_SEC)
        & (df['segment_speech_ratio'].fillna(0) >= MIN_TRAIN_SEGMENT_SPEECH_RATIO)
        & (df['segment_clip_ratio'].fillna(1) < MAX_TRAIN_CLIP_RATIO)
    )
    return df


def prepare_channels_for_save(channels_df: pd.DataFrame) -> pd.DataFrame:
    df = channels_df.copy()
    if 'vad_intervals' in df.columns:
        df['vad_intervals_json'] = df['vad_intervals'].apply(json_dumps_safe)
        df = df.drop(columns=['vad_intervals'])
    if 'vad_merged_intervals' in df.columns:
        df['vad_merged_intervals_json'] = df['vad_merged_intervals'].apply(json_dumps_safe)
        df = df.drop(columns=['vad_merged_intervals'])
    return df


def save_progress(calls_df: pd.DataFrame, channels_df: pd.DataFrame, segments_df: pd.DataFrame, suffix: str):
    calls_df.to_parquet(CHECKPOINT_DIR / f'calls_{suffix}.parquet', index=False)
    prepare_channels_for_save(channels_df).to_parquet(CHECKPOINT_DIR / f'channels_{suffix}.parquet', index=False)
    segments_df.to_parquet(CHECKPOINT_DIR / f'segments_{suffix}.parquet', index=False)
    print('Saved checkpoint:', suffix)


def save_audio_prep_batch(batch_index: int, call_rows, channel_rows, segment_rows):
    suffix = f'batch_{batch_index:07d}'
    calls_part = pd.DataFrame(call_rows)
    channels_part = pd.DataFrame(channel_rows)
    segments_part = pd.DataFrame(segment_rows)

    if len(segments_part) > 0:
        segments_part = mark_audio_trainable(segments_part)

    calls_part.to_parquet(AUDIO_PREP_BATCH_DIR / f'calls_{suffix}.parquet', index=False)
    prepare_channels_for_save(channels_part).to_parquet(AUDIO_PREP_BATCH_DIR / f'channels_{suffix}.parquet', index=False)
    segments_part.to_parquet(AUDIO_PREP_BATCH_DIR / f'segments_{suffix}.parquet', index=False)
    return calls_part, channels_part, segments_part


def load_latest_audio_prep_checkpoint():
    files = sorted(CHECKPOINT_DIR.glob('segments_*.parquet'))
    if not files:
        return None, None, None
    latest_seg = files[-1]
    suffix = latest_seg.stem.replace('segments_', '')
    calls_path = CHECKPOINT_DIR / f'calls_{suffix}.parquet'
    channels_path = CHECKPOINT_DIR / f'channels_{suffix}.parquet'
    if not calls_path.exists() or not channels_path.exists():
        return None, None, None
    print('Loaded checkpoint:', suffix)
    return pd.read_parquet(calls_path), pd.read_parquet(channels_path), pd.read_parquet(latest_seg)


def load_all_audio_prep_outputs():
    call_files = sorted(AUDIO_PREP_BATCH_DIR.glob('calls_batch_*.parquet'))
    channel_files = sorted(AUDIO_PREP_BATCH_DIR.glob('channels_batch_*.parquet'))
    segment_files = sorted(AUDIO_PREP_BATCH_DIR.glob('segments_batch_*.parquet'))

    calls = pd.concat([pd.read_parquet(p) for p in call_files], ignore_index=True) if call_files else pd.DataFrame()
    channels = pd.concat([pd.read_parquet(p) for p in channel_files], ignore_index=True) if channel_files else pd.DataFrame()
    segments = pd.concat([pd.read_parquet(p) for p in segment_files], ignore_index=True) if segment_files else pd.DataFrame()

    if len(calls) and 'call_id' in calls.columns:
        calls = calls.drop_duplicates(subset=['call_id'], keep='last').reset_index(drop=True)
    if len(channels) and {'call_id', 'channel_idx'}.issubset(channels.columns):
        channels = channels.drop_duplicates(subset=['call_id', 'channel_idx'], keep='last').reset_index(drop=True)
    if len(segments) and 'segment_id' in segments.columns:
        segments = segments.drop_duplicates(subset=['segment_id'], keep='last').reset_index(drop=True)
        segments = mark_audio_trainable(segments)

    return calls, channels, segments


def load_processed_call_ids_from_batches() -> set:
    ids = set()
    for p in sorted(AUDIO_PREP_BATCH_DIR.glob('calls_batch_*.parquet')):
        try:
            part = pd.read_parquet(p, columns=['call_id'])
            ids.update(part['call_id'].astype(str).tolist())
        except Exception:
            pass
    return ids


def failed_process_result(src_path: Path, error: Exception) -> Dict[str, List[Dict[str, Any]]]:
    return {
        'calls': [{
            'call_id': safe_call_id_from_path(src_path),
            'src_path': str(src_path),
            'decode_ok': False,
            'decode_error': repr(error),
        }],
        'channels': [],
        'segments': [],
    }

# =========================================================
# RUN PARALLEL AUDIO PREP FOR ALL 2026 FILES
# =========================================================

processed_call_ids = load_processed_call_ids_from_batches() if PENDING_ONLY else set()
pending_files = [p for p in selected_files if safe_call_id_from_path(p) not in processed_call_ids]

print('Already processed calls:', len(processed_call_ids))
print('Pending files:', len(pending_files))
print('Audio prep workers:', AUDIO_PREP_WORKERS)
print('Batch file count:', BATCH_FILE_COUNT)

batch_counter_start = len(list(AUDIO_PREP_BATCH_DIR.glob('calls_batch_*.parquet')))

with ThreadPoolExecutor(max_workers=AUDIO_PREP_WORKERS) as executor:
    for offset in range(0, len(pending_files), BATCH_FILE_COUNT):
        batch_files = pending_files[offset:offset + BATCH_FILE_COUNT]
        batch_index = batch_counter_start + (offset // BATCH_FILE_COUNT)

        print(f'\nProcessing batch {batch_index} with {len(batch_files)} files')

        futures = {executor.submit(process_one_call, Path(src_path)): Path(src_path) for src_path in batch_files}

        batch_call_rows = []
        batch_channel_rows = []
        batch_segment_rows = []

        for future in tqdm(as_completed(futures), total=len(futures), desc='Processing calls'):
            src_path = futures[future]
            try:
                result = future.result()
            except Exception as e:
                result = failed_process_result(src_path, e)

            batch_call_rows.extend(result['calls'])
            batch_channel_rows.extend(result['channels'])
            batch_segment_rows.extend(result['segments'])

        calls_part, channels_part, segments_part = save_audio_prep_batch(
            batch_index=batch_index,
            call_rows=batch_call_rows,
            channel_rows=batch_channel_rows,
            segment_rows=batch_segment_rows,
        )

        cleanup_tmp_dirs()

        if len(segments_part) > 0 and 'is_audio_trainable' in segments_part.columns:
            batch_trainable_sec = segments_part.loc[segments_part['is_audio_trainable'], 'usable_speech_sec'].sum()
        else:
            batch_trainable_sec = 0.0

        print('Saved batch:', batch_index)
        print('Batch calls:', len(calls_part))
        print('Batch channels:', len(channels_part))
        print('Batch segments:', len(segments_part))
        print('Batch trainable speech hours:', round(batch_trainable_sec / 3600, 4))

calls_df, channels_df, segments_df = load_all_audio_prep_outputs()
save_progress(calls_df, channels_df, segments_df, suffix='final_audio_prep')

calls_df.to_parquet(MANIFESTS_DIR / 'calls_all.parquet', index=False)
channels_df.to_parquet(MANIFESTS_DIR / 'channels_all.parquet', index=False)
segments_df.to_parquet(MANIFESTS_DIR / 'segments_all.parquet', index=False)

print('\nFinal audio prep outputs')
print('calls:', len(calls_df))
print('channels:', len(channels_df))
print('segments:', len(segments_df))
if len(segments_df) > 0 and 'is_audio_trainable' in segments_df.columns:
    print('audio-trainable chunks:', int(segments_df['is_audio_trainable'].sum()))
    print('audio-trainable speech hours:', segments_df.loc[segments_df['is_audio_trainable'], 'usable_speech_sec'].sum() / 3600)

# =========================================================
# AUDIO PREP SUMMARY
# =========================================================

if 'segments_df' not in globals() or len(segments_df) == 0:
    calls_df, channels_df, segments_df = load_all_audio_prep_outputs()

print('Calls:', len(calls_df))
print('Channels:', len(channels_df))
print('Segments:', len(segments_df))

if len(calls_df):
    print('\nDecode status:')
    display(calls_df['decode_ok'].value_counts(dropna=False))

if len(segments_df):
    print('\nAll segment duration:')
    display(segments_df['duration'].describe())

    train_mask = segments_df['is_audio_trainable'].fillna(False)
    print('\nTrainable segment duration:')
    display(segments_df.loc[train_mask, 'duration'].describe())

    print('\nTrainable speech ratio:')
    display(segments_df.loc[train_mask, 'segment_speech_ratio'].describe())

    print('Total all segment duration hours:', segments_df['duration'].sum() / 3600)
    print('Total speech-active hours:', segments_df['usable_speech_sec'].sum() / 3600)
    print('Trainable speech-active hours:', segments_df.loc[train_mask, 'usable_speech_sec'].sum() / 3600)

    segments_df.to_csv(MANIFESTS_DIR / 'segments_all.csv', index=False)

# =========================================================
# RECONSTRUCTION AND TIMING AUDIT
# =========================================================
# reconstruct_call_from_segments creates a full-length multichannel file by
# inserting kept speech segments at their original sample positions. Non-kept
# regions become silence.
#
# export_original_call_to_canonical_wav_and_opus decodes the original Opus into
# a full 16 kHz multichannel WAV and then Opus. Use this when you need full
# audio preserved, including silence, noise, hold music, and background sound.


def channel_to_index(channel_value) -> int:
    if pd.isna(channel_value):
        return 0
    text = str(channel_value)
    m = re.search(r'(\d+)$', text)
    return int(m.group(1)) if m else 0


def reconstruct_call_from_segments(call_id: str, segments_df: pd.DataFrame, calls_df: pd.DataFrame, out_wav: Path, sr: int = TARGET_SR) -> Path:
    out_wav = Path(out_wav)
    out_wav.parent.mkdir(parents=True, exist_ok=True)

    call_segments = segments_df[
        (segments_df['call_id'].astype(str) == str(call_id))
        & (segments_df['segment_error'].isna())
    ].copy()

    call_rows = calls_df[calls_df['call_id'].astype(str) == str(call_id)]
    if len(call_rows) == 0:
        raise ValueError(f'Call ID not found: {call_id}')

    call_row = call_rows.iloc[0]
    total_samples = int(call_row.get('canonical_duration_samples') or call_row.get('call_duration_samples') or 0)
    if total_samples <= 0:
        if len(call_segments) == 0:
            raise ValueError(f'No duration metadata and no segments for call: {call_id}')
        total_samples = int(call_segments['end_sample'].max())

    n_channels = int(call_row.get('channels') or 1)
    if len(call_segments) and 'channel_idx' in call_segments.columns:
        n_channels = max(n_channels, int(call_segments['channel_idx'].max()) + 1)

    tracks = np.zeros((total_samples, n_channels), dtype=np.float32)

    for _, row in call_segments.sort_values(['channel_idx', 'start_sample']).iterrows():
        seg_path = Path(row['audio_filepath'])
        if not seg_path.exists():
            continue

        seg_audio, seg_sr = sf.read(str(seg_path), dtype='float32', always_2d=False)
        if seg_sr != sr:
            raise ValueError(f'Unexpected segment sample rate {seg_sr}: {seg_path}')
        if getattr(seg_audio, 'ndim', 1) > 1:
            seg_audio = seg_audio.mean(axis=1)

        ch_idx = int(row['channel_idx']) if 'channel_idx' in row and not pd.isna(row['channel_idx']) else channel_to_index(row['channel'])
        start = int(row['start_sample']) if 'start_sample' in row and not pd.isna(row['start_sample']) else int(round(float(row['start_sec']) * sr))
        end = min(total_samples, start + len(seg_audio))
        if start < 0 or start >= total_samples or end <= start:
            continue

        tracks[start:end, ch_idx] += seg_audio[:end - start]

    sf.write(str(out_wav), np.clip(tracks, -1.0, 1.0), sr, subtype=SEGMENT_SUBTYPE)
    return out_wav


def merge_persisted_full_channels(call_id: str, channels_df: pd.DataFrame, calls_df: pd.DataFrame, out_wav: Path, sr: int = TARGET_SR) -> Path:
    out_wav = Path(out_wav)
    out_wav.parent.mkdir(parents=True, exist_ok=True)

    call_channels = channels_df[
        (channels_df['call_id'].astype(str) == str(call_id))
        & (channels_df['canonical_path_persisted'] == True)
    ].copy()
    if len(call_channels) == 0:
        raise ValueError('No persisted full channels found. Set KEEP_FULL_CHANNEL_AUDIO=True before audio prep.')

    call_row = calls_df[calls_df['call_id'].astype(str) == str(call_id)].iloc[0]
    total_samples = int(call_row.get('canonical_duration_samples') or call_channels['duration_samples'].max())
    n_channels = int(call_row.get('channels') or len(call_channels))

    first_path = Path(call_channels.iloc[0]['canonical_path'])
    first_type = str(call_channels.iloc[0].get('canonical_path_type', ''))

    if first_type == 'multichannel_16k_wav' or call_channels['canonical_path'].nunique() == 1:
        audio, file_sr = sf.read(str(first_path), dtype='float32', always_2d=True)
        if file_sr != sr:
            raise ValueError(f'Unexpected sample rate {file_sr}: {first_path}')
        if audio.shape[1] < n_channels:
            padded = np.zeros((audio.shape[0], n_channels), dtype=np.float32)
            padded[:, :audio.shape[1]] = audio
            audio = padded
        audio = audio[:total_samples, :n_channels]
        if audio.shape[0] < total_samples:
            padded = np.zeros((total_samples, n_channels), dtype=np.float32)
            padded[:audio.shape[0], :] = audio
            audio = padded
        sf.write(str(out_wav), np.clip(audio, -1.0, 1.0), sr, subtype=SEGMENT_SUBTYPE)
        return out_wav

    tracks = np.zeros((total_samples, n_channels), dtype=np.float32)
    for _, row in call_channels.sort_values('channel_idx').iterrows():
        ch_idx = int(row['channel_idx'])
        path = Path(row['canonical_path'])
        audio, ch_sr = sf.read(str(path), dtype='float32', always_2d=False)
        if ch_sr != sr:
            raise ValueError(f'Unexpected channel sample rate {ch_sr}: {path}')
        if getattr(audio, 'ndim', 1) > 1:
            audio = audio.mean(axis=1)
        n = min(total_samples, len(audio))
        tracks[:n, ch_idx] = audio[:n]

    sf.write(str(out_wav), np.clip(tracks, -1.0, 1.0), sr, subtype=SEGMENT_SUBTYPE)
    return out_wav


def encode_wav_to_opus(in_wav: Path, out_opus: Path, bitrate: str = OPUS_EXPORT_BITRATE) -> Path:
    out_opus = Path(out_opus)
    out_opus.parent.mkdir(parents=True, exist_ok=True)
    cmd = ffmpeg_base_cmd() + [
        '-y',
        '-i', str(in_wav),
        '-c:a', 'libopus',
        '-b:a', bitrate,
        '-application', 'voip',
        '-frame_duration', '20',
        '-vbr', 'on',
        str(out_opus),
    ]
    run_cmd(cmd, timeout=FFMPEG_TIMEOUT_SEC)
    return out_opus


def export_original_call_to_canonical_wav_and_opus(call_id: str, calls_df: pd.DataFrame, make_opus: bool = True) -> Dict[str, Any]:
    call_row = calls_df[calls_df['call_id'].astype(str) == str(call_id)].iloc[0]
    src_path = Path(call_row['src_path'])
    out_dir = RECONSTRUCTED_DIR / str(call_id) / 'from_original'
    out_wav = out_dir / 'original_decoded_16k_multichannel.wav'
    out_opus = out_dir / 'original_decoded_16k_multichannel.opus'

    decode_res = decode_opus_to_16k_multichannel_wav(src_path, out_dir / 'tmp_decode')
    if not decode_res['decode_ok']:
        raise RuntimeError(decode_res['decode_error'])
    shutil.copy2(decode_res['decoded_path'], out_wav)
    if make_opus:
        encode_wav_to_opus(out_wav, out_opus)

    return {
        'call_id': call_id,
        'source': 'original',
        'wav_path': str(out_wav),
        'opus_path': str(out_opus) if make_opus else None,
        'canonical_duration_sec': decode_res['canonical_duration_sec'],
        'canonical_duration_samples': decode_res['canonical_duration_samples'],
    }


def validate_reconstruction_duration(call_id: str, reconstructed_path: Path, calls_df: pd.DataFrame, tolerance_sec: float = RECONSTRUCTION_DURATION_TOLERANCE_SEC) -> Dict[str, Any]:
    call_row = calls_df[calls_df['call_id'].astype(str) == str(call_id)].iloc[0]
    expected = float(call_row.get('canonical_duration_sec') or call_row.get('duration_sec'))
    got = safe_duration_sec(Path(reconstructed_path))
    delta = None if got is None else abs(float(got) - expected)
    return {
        'call_id': call_id,
        'path': str(reconstructed_path),
        'expected_duration_sec': expected,
        'actual_duration_sec': got,
        'duration_delta_sec': delta,
        'duration_ok': bool(delta is not None and delta <= tolerance_sec),
    }


def validate_segment_placement(call_id: str, reconstructed_wav: Path, segments_df: pd.DataFrame, max_segments: int = 100) -> Dict[str, Any]:
    audio, sr = sf.read(str(reconstructed_wav), dtype='float32', always_2d=True)
    if sr != TARGET_SR:
        raise ValueError(f'Unexpected reconstructed sample rate: {sr}')

    call_segments = segments_df[
        (segments_df['call_id'].astype(str) == str(call_id))
        & (segments_df['segment_error'].isna())
    ].copy()
    if len(call_segments) > max_segments:
        call_segments = call_segments.sample(max_segments, random_state=SEED)

    checked = 0
    max_abs_error = 0.0
    failures = 0

    for _, row in call_segments.iterrows():
        seg_path = Path(row['audio_filepath'])
        if not seg_path.exists():
            continue
        seg_audio, seg_sr = sf.read(str(seg_path), dtype='float32', always_2d=False)
        if seg_sr != TARGET_SR:
            continue
        if getattr(seg_audio, 'ndim', 1) > 1:
            seg_audio = seg_audio.mean(axis=1)

        ch_idx = int(row['channel_idx']) if 'channel_idx' in row and not pd.isna(row['channel_idx']) else channel_to_index(row['channel'])
        start = int(row['start_sample'])
        end = min(audio.shape[0], start + len(seg_audio))
        if end <= start:
            failures += 1
            continue

        rec_slice = audio[start:end, ch_idx]
        seg_slice = seg_audio[:end - start]
        err = float(np.max(np.abs(rec_slice - seg_slice))) if len(seg_slice) else 0.0
        max_abs_error = max(max_abs_error, err)
        checked += 1
        if err > RECONSTRUCTION_ALIGNMENT_TOLERANCE:
            failures += 1

    return {
        'call_id': call_id,
        'checked_segments': checked,
        'placement_failures': failures,
        'max_abs_error': max_abs_error,
        'placement_ok': bool(failures == 0),
    }


def reconstruct_call_to_wav_and_opus(call_id: str, source: str = 'segments', make_opus: bool = True) -> Dict[str, Any]:
    call_dir = RECONSTRUCTED_DIR / str(call_id) / source
    wav_path = call_dir / 'reconstructed_16k_multichannel.wav'
    opus_path = call_dir / 'reconstructed_16k_multichannel.opus'

    if source == 'segments':
        reconstruct_call_from_segments(call_id, segments_df, calls_df, wav_path)
        placement_check = validate_segment_placement(call_id, wav_path, segments_df)
    elif source == 'full_channels':
        merge_persisted_full_channels(call_id, channels_df, calls_df, wav_path)
        placement_check = {'checked_segments': None, 'placement_failures': None, 'max_abs_error': None, 'placement_ok': True}
    elif source == 'original':
        result = export_original_call_to_canonical_wav_and_opus(call_id, calls_df, make_opus=make_opus)
        wav_path = Path(result['wav_path'])
        opus_path = Path(result['opus_path']) if make_opus else opus_path
        placement_check = {'checked_segments': None, 'placement_failures': None, 'max_abs_error': None, 'placement_ok': True}
    else:
        raise ValueError("source must be 'segments', 'full_channels', or 'original'")

    wav_duration_check = validate_reconstruction_duration(call_id, wav_path, calls_df)
    opus_duration_check = None
    if make_opus and source != 'original':
        encode_wav_to_opus(wav_path, opus_path)
        opus_duration_check = validate_reconstruction_duration(call_id, opus_path, calls_df)
    elif make_opus:
        opus_duration_check = validate_reconstruction_duration(call_id, opus_path, calls_df)

    out = {
        'call_id': call_id,
        'source': source,
        'wav_path': str(wav_path),
        'opus_path': str(opus_path) if make_opus else None,
        **{f'wav_{k}': v for k, v in wav_duration_check.items() if k != 'call_id'},
        **{f'placement_{k}': v for k, v in placement_check.items() if k != 'call_id'},
    }
    if opus_duration_check:
        out.update({f'opus_{k}': v for k, v in opus_duration_check.items() if k != 'call_id'})
    return out


if RUN_RECONSTRUCTION_AUDIT and len(calls_df) > 0 and len(segments_df) > 0:
    audit_call_ids = segments_df[segments_df['segment_error'].isna()]['call_id'].drop_duplicates().head(RECONSTRUCT_AUDIT_CALLS).astype(str).tolist()
    audit_rows = []
    for call_id in tqdm(audit_call_ids, desc='Reconstruction audit'):
        for source in ['segments', 'original']:
            try:
                audit_rows.append(reconstruct_call_to_wav_and_opus(call_id, source=source, make_opus=True))
            except Exception as e:
                audit_rows.append({'call_id': call_id, 'source': source, 'error': repr(e)})

    reconstruction_audit_df = pd.DataFrame(audit_rows)
    reconstruction_audit_df.to_csv(LOGS_DIR / 'reconstruction_audit.csv', index=False)
    display(reconstruction_audit_df)

