        print('speech_ratio:', row.get('segment_speech_ratio'))
        print('clip_ratio:', row.get('segment_clip_ratio'))
        print('is_audio_trainable:', row.get('is_audio_trainable'))
        print('path:', row['audio_filepath'])
        display(Audio(filename=row['audio_filepath']))

