def load_existing_csv(path: Path) -> Tuple[List[Dict[str, Any]], set]:
    path = Path(path)
    if not path.exists():
        return [], set()
    old_df = pd.read_csv(path)
    if 'segment_id' not in old_df.columns:
        return [], set()
    rows = old_df.to_dict('records')
    done_ids = set(old_df['segment_id'].astype(str))
    return rows, done_ids


def run_row_engine(
    df: pd.DataFrame,
    row_fn: Callable[[pd.Series], Dict[str, Any]],
    output_path: Path,
    desc: str,
    batch_save_every: int = ASR_BATCH_SAVE_EVERY,
) -> pd.DataFrame:
    output_path = Path(output_path)
    rows, done_ids = load_existing_csv(output_path)
    if done_ids:
        print(f'Resuming {desc}. Already done:', len(done_ids))

    pending_df = df[~df['segment_id'].astype(str).isin(done_ids)].copy()
    print(desc, 'pending:', len(pending_df), 'of', len(df))

    for _, row in tqdm(pending_df.iterrows(), total=len(pending_df), desc=desc):
        sid = str(row['segment_id'])
        try:
            result = row_fn(row)
        except Exception as e:
            result = {'segment_id': sid, 'error': repr(e)}
        result['segment_id'] = sid
        rows.append(result)

        if len(rows) % batch_save_every == 0:
            pd.DataFrame(rows).to_csv(output_path, index=False)

    out_df = pd.DataFrame(rows)
    out_df.to_csv(output_path, index=False)
    return out_df


def run_batch_engine(
    df: pd.DataFrame,
    batch_fn: Callable[[List[str]], Tuple[List[str], List[Optional[str]]]],
    output_col: str,
    error_col: str,
    output_path: Path,
    batch_size: int,
    desc: str,
    batch_save_every: int = ASR_BATCH_SAVE_EVERY,
) -> pd.DataFrame:
    output_path = Path(output_path)
    rows, done_ids = load_existing_csv(output_path)
    if done_ids:
        print(f'Resuming {desc}. Already done:', len(done_ids))

    pending_df = df[~df['segment_id'].astype(str).isin(done_ids)].copy()
    print(desc, 'pending:', len(pending_df), 'of', len(df))

    for start in tqdm(range(0, len(pending_df), batch_size), desc=desc):
        batch = pending_df.iloc[start:start + batch_size]
        paths = batch['audio_filepath'].astype(str).tolist()
        segment_ids = batch['segment_id'].astype(str).tolist()

        try:
            texts, errors = batch_fn(paths)
        except Exception as e:
            texts = [''] * len(segment_ids)
            errors = [repr(e)] * len(segment_ids)

        if len(texts) != len(segment_ids):
            got = len(texts)
            texts = [''] * len(segment_ids)
            errors = [f'Batch output length mismatch: got {got}, expected {len(segment_ids)}'] * len(segment_ids)

        for sid, text, err in zip(segment_ids, texts, errors):
            rows.append({'segment_id': sid, output_col: str(text or '').strip(), error_col: err})

        if len(rows) % batch_save_every < batch_size:
            pd.DataFrame(rows).to_csv(output_path, index=False)

    out_df = pd.DataFrame(rows)
    out_df.to_csv(output_path, index=False)
    return out_df


def load_audio_mono_np(path: Path, sr: int = TARGET_SR) -> np.ndarray:
    audio, _ = librosa.load(str(path), sr=sr, mono=True)
    return audio.astype(np.float32)


def load_wav_16k_mono_tensor(path: str) -> torch.Tensor:
    wav, sr = torchaudio.load(path, normalize=True)
    if wav.shape[0] > 1:
        wav = wav.mean(dim=0, keepdim=True)
    if sr != TARGET_SR:
        wav = torchaudio.functional.resample(wav, sr, TARGET_SR)
    return wav.squeeze(0)


def move_inputs_to_device_dtype(batch, device, dtype=None):
    moved = {}
    for k, v in batch.items():
        if hasattr(v, 'to'):
            if dtype is not None and torch.is_floating_point(v):
                moved[k] = v.to(device=device, dtype=dtype)
            else:
                moved[k] = v.to(device=device)
        else:
            moved[k] = v
    return moved

