import gc
import time
import pandas as pd
import torch
from faster_whisper import WhisperModel, BatchedInferencePipeline
from faster_whisper.audio import decode_audio

def clear_cuda():
    gc.collect()
    if torch.cuda.is_available():
        torch.cuda.empty_cache()
        torch.cuda.ipc_collect()

def benchmark_faster_whisper(
    df: pd.DataFrame,
    model_dir,
    compute_type="float16",
    beam_size=1,
    internal_batch_size=16,
    vad_filter=False,
    num_workers=1,
    n=500,
):
    sample_df = df.sample(
        n=min(n, len(df)),
        random_state=42,
    ).reset_index(drop=True)

    clear_cuda()

    base_model = WhisperModel(
        str(model_dir),
        device="cuda",
        compute_type=compute_type,
        local_files_only=True,
        cpu_threads=max(1, CPU_COUNT // 2),
        num_workers=num_workers,
    )
    model = BatchedInferencePipeline(model=base_model)

    # Warmup
    for path in sample_df["audio_filepath"].astype(str).head(5):
        audio = decode_audio(path, sampling_rate=16000)
        segments, info = model.transcribe(
            audio,
            language=None,
            beam_size=beam_size,
            batch_size=internal_batch_size,
            vad_filter=vad_filter,
            condition_on_previous_text=False,
            without_timestamps=True,
        )
        _ = " ".join(s.text for s in segments)

    torch.cuda.synchronize()
    t0 = time.perf_counter()

    total_audio_seconds = 0.0
    non_empty = 0
    errors = 0

    for path in sample_df["audio_filepath"].astype(str):
        try:
            audio = decode_audio(path, sampling_rate=16000)
            total_audio_seconds += len(audio) / 16000.0

            segments, info = model.transcribe(
                audio,
                language=None,
                beam_size=beam_size,
                batch_size=internal_batch_size,
                vad_filter=vad_filter,
                condition_on_previous_text=False,
                without_timestamps=True,
            )
            text = " ".join(s.text.strip() for s in segments).strip()
            non_empty += bool(text)

        except Exception:
            errors += 1

    torch.cuda.synchronize()
    wall = time.perf_counter() - t0

    del model
    del base_model
    clear_cuda()

    return {
        "model_dir": str(model_dir),
        "compute_type": compute_type,
        "beam_size": beam_size,
        "internal_batch_size": internal_batch_size,
        "vad_filter": vad_filter,
        "num_workers": num_workers,
        "files": len(sample_df),
        "wall_seconds": wall,
        "files_per_second": len(sample_df) / wall,
        "audio_hours": total_audio_seconds / 3600,
        "audio_hours_per_wall_hour": (total_audio_seconds / 3600) / (wall / 3600),
        "non_empty": non_empty,
        "errors": errors,
    }

configs = [
    # current-ish
    dict(compute_type="float16", beam_size=5, internal_batch_size=32, vad_filter=False, num_workers=1),

    # recommended first pass
    dict(compute_type="float16", beam_size=1, internal_batch_size=16, vad_filter=False, num_workers=1),
    dict(compute_type="float16", beam_size=1, internal_batch_size=32, vad_filter=False, num_workers=1),

    # sometimes useful, not guaranteed faster
    dict(compute_type="int8_float16", beam_size=1, internal_batch_size=16, vad_filter=False, num_workers=1),
    dict(compute_type="int8_float16", beam_size=1, internal_batch_size=32, vad_filter=False, num_workers=1),

    # only if your files have long silence
    dict(compute_type="float16", beam_size=1, internal_batch_size=16, vad_filter=True, num_workers=1),
]

results = []

for cfg in configs:
    print("Running:", cfg)
    out = benchmark_faster_whisper(
        whisper_input_df,
        WHISPER_MODEL_DIR,
        n=1000,
        **cfg,
    )
    print(out)
    results.append(out)

bench_df = pd.DataFrame(results).sort_values(
    ["audio_hours_per_wall_hour", "files_per_second"],
    ascending=False,
)

display(bench_df)

best = bench_df.iloc[0]
estimated_hours = len(whisper_input_df) / best["files_per_second"] / 3600
print("Estimated full runtime hours:", estimated_hours)

