import gc
import time
from pathlib import Path
import pandas as pd
import torch
from faster_whisper import WhisperModel, BatchedInferencePipeline
from faster_whisper.audio import decode_audio


def clear_cuda():
    gc.collect()
    if torch.cuda.is_available():
        torch.cuda.empty_cache()
        torch.cuda.ipc_collect()


def benchmark_faster_whisper(
    df: pd.DataFrame,
    model_dir,
    compute_type="float16",
    beam_size=1,
    internal_batch_size=16,
    vad_filter=False,
    num_workers=1,
    n=1000,
    log_every=50,
):
    sample_df = df.sample(
        n=min(n, len(df)),
        random_state=42,
    ).reset_index(drop=True)

    print("=" * 80, flush=True)
    print("Benchmark config", flush=True)
    print("model_dir:", model_dir, flush=True)
    print("compute_type:", compute_type, flush=True)
    print("beam_size:", beam_size, flush=True)
    print("internal_batch_size:", internal_batch_size, flush=True)
    print("vad_filter:", vad_filter, flush=True)
    print("num_workers:", num_workers, flush=True)
    print("files:", len(sample_df), flush=True)
    print("=" * 80, flush=True)

    clear_cuda()

    print("Loading model...", flush=True)

    base_model = WhisperModel(
        str(model_dir),
        device="cuda" if torch.cuda.is_available() else "cpu",
        compute_type=compute_type,
        local_files_only=True,
        cpu_threads=max(1, CPU_COUNT // 2),
        num_workers=num_workers,
    )

    model = BatchedInferencePipeline(model=base_model)

    print("Model loaded.", flush=True)
    print("Warmup started...", flush=True)

    warmup_paths = sample_df["audio_filepath"].astype(str).head(5).tolist()

    for i, path in enumerate(warmup_paths, start=1):
        print(f"Warmup {i}/{len(warmup_paths)}: {Path(path).name}", flush=True)

        audio = decode_audio(path, sampling_rate=16000)

        segments, info = model.transcribe(
            audio,
            language=None,
            beam_size=beam_size,
            batch_size=internal_batch_size,
            vad_filter=vad_filter,
            condition_on_previous_text=False,
            without_timestamps=True,
        )

        _ = " ".join(s.text for s in segments)

    if torch.cuda.is_available():
        torch.cuda.synchronize()

    print("Warmup done.", flush=True)
    print("Timed benchmark started...", flush=True)

    t0 = time.perf_counter()

    total_audio_seconds = 0.0
    non_empty = 0
    errors = 0

    paths = sample_df["audio_filepath"].astype(str).tolist()

    for i, path in enumerate(paths, start=1):
        file_t0 = time.perf_counter()

        try:
            audio = decode_audio(path, sampling_rate=16000)
            audio_seconds = len(audio) / 16000.0
            total_audio_seconds += audio_seconds

            segments, info = model.transcribe(
                audio,
                language=None,
                beam_size=beam_size,
                batch_size=internal_batch_size,
                vad_filter=vad_filter,
                condition_on_previous_text=False,
                without_timestamps=True,
            )

            text = " ".join(s.text.strip() for s in segments).strip()
            non_empty += bool(text)
            status = "ok"

        except Exception as e:
            errors += 1
            audio_seconds = 0.0
            status = f"error: {repr(e)}"

        file_wall = time.perf_counter() - file_t0

        if i == 1 or i % log_every == 0 or i == len(paths):
            elapsed = time.perf_counter() - t0
            files_per_second = i / elapsed if elapsed > 0 else 0.0
            eta_seconds = (len(paths) - i) / files_per_second if files_per_second > 0 else 0.0

            print(
                f"[{i}/{len(paths)}] "
                f"elapsed={elapsed:.1f}s "
                f"eta={eta_seconds / 60:.1f}m "
                f"fps={files_per_second:.3f} "
                f"audio_sec={audio_seconds:.2f} "
                f"file_wall={file_wall:.2f}s "
                f"status={status} "
                f"file={Path(path).name}",
                flush=True,
            )

    if torch.cuda.is_available():
        torch.cuda.synchronize()

    wall = time.perf_counter() - t0

    del model
    del base_model
    clear_cuda()

    return {
        "model_dir": str(model_dir),
        "compute_type": compute_type,
        "beam_size": beam_size,
        "internal_batch_size": internal_batch_size,
        "vad_filter": vad_filter,
        "num_workers": num_workers,
        "files": len(sample_df),
        "wall_seconds": wall,
        "files_per_second": len(sample_df) / wall if wall > 0 else 0.0,
        "audio_hours": total_audio_seconds / 3600,
        "audio_hours_per_wall_hour": (
            (total_audio_seconds / 3600) / (wall / 3600)
            if wall > 0 else 0.0
        ),
        "avg_file_wall_seconds": wall / len(sample_df) if len(sample_df) > 0 else None,
        "non_empty": non_empty,
        "errors": errors,
    }

out = benchmark_faster_whisper(
    whisper_input_df,
    TURBO_MODEL_DIR,
    n=1000,
    log_every=50,
    compute_type="float16",
    beam_size=1,
    internal_batch_size=16,
    vad_filter=False,
    num_workers=1,
)

print(out)

