import gc
import time
from pathlib import Path

import pandas as pd
import torch
from transformers import AutoModelForSpeechSeq2Seq, AutoProcessor, pipeline


def clear_cuda():
    gc.collect()
    if torch.cuda.is_available():
        torch.cuda.empty_cache()
        torch.cuda.ipc_collect()


HF_TURBO_MODEL_DIR = Path("/mnt/amc-data/pipeline/models/openai-whisper-large-v3-turbo-hf")

if HF_TURBO_MODEL_DIR.exists():
    HF_MODEL_NAME_OR_PATH = str(HF_TURBO_MODEL_DIR)
    HF_LOCAL_ONLY = True
else:
    # Requires internet. If no internet, download this model separately into HF_TURBO_MODEL_DIR.
    HF_MODEL_NAME_OR_PATH = "openai/whisper-large-v3-turbo"
    HF_LOCAL_ONLY = False

print("HF model:", HF_MODEL_NAME_OR_PATH)
print("local_files_only:", HF_LOCAL_ONLY)

clear_cuda()

torch_dtype = torch.float16

processor = AutoProcessor.from_pretrained(
    HF_MODEL_NAME_OR_PATH,
    local_files_only=HF_LOCAL_ONLY,
)

try:
    hf_model = AutoModelForSpeechSeq2Seq.from_pretrained(
        HF_MODEL_NAME_OR_PATH,
        torch_dtype=torch_dtype,
        low_cpu_mem_usage=True,
        use_safetensors=True,
        local_files_only=HF_LOCAL_ONLY,
        attn_implementation="sdpa",
    ).to("cuda")
except TypeError:
    hf_model = AutoModelForSpeechSeq2Seq.from_pretrained(
        HF_MODEL_NAME_OR_PATH,
        torch_dtype=torch_dtype,
        low_cpu_mem_usage=True,
        use_safetensors=True,
        local_files_only=HF_LOCAL_ONLY,
    ).to("cuda")

hf_asr = pipeline(
    task="automatic-speech-recognition",
    model=hf_model,
    tokenizer=processor.tokenizer,
    feature_extractor=processor.feature_extractor,
    torch_dtype=torch_dtype,
    device=0,
)

print("HF ASR pipeline loaded.")

def benchmark_hf_batched(
    df: pd.DataFrame,
    n: int = 1000,
    gpu_batch_size: int = 32,
    outer_batch_size: int = 512,
    return_language: bool = False,
    return_timestamps: bool = False,
    chunk_length_s=None,
):
    sample_df = df.sample(
        n=min(n, len(df)),
        random_state=42,
    ).reset_index(drop=True)

    paths = sample_df["audio_filepath"].astype(str).tolist()

    print("=" * 80, flush=True)
    print("HF batched benchmark", flush=True)
    print("files:", len(paths), flush=True)
    print("gpu_batch_size:", gpu_batch_size, flush=True)
    print("outer_batch_size:", outer_batch_size, flush=True)
    print("return_language:", return_language, flush=True)
    print("return_timestamps:", return_timestamps, flush=True)
    print("chunk_length_s:", chunk_length_s, flush=True)
    print("=" * 80, flush=True)

    call_kwargs = {
        "batch_size": gpu_batch_size,
        "generate_kwargs": {
            "task": "transcribe",
            "num_beams": 1,
            "max_new_tokens": 224,
        },
    }

    if return_language:
        call_kwargs["return_language"] = True

    if return_timestamps:
        call_kwargs["return_timestamps"] = True

    if chunk_length_s is not None:
        call_kwargs["chunk_length_s"] = chunk_length_s

    # Warmup
    warmup_paths = paths[:min(len(paths), gpu_batch_size)]
    _ = hf_asr(warmup_paths, **call_kwargs)

    torch.cuda.synchronize()
    t0 = time.perf_counter()

    done = 0
    non_empty = 0
    language_found = 0
    errors = 0

    for start in range(0, len(paths), outer_batch_size):
        batch_paths = paths[start:start + outer_batch_size]

        try:
            outputs = hf_asr(batch_paths, **call_kwargs)

            if isinstance(outputs, dict):
                outputs = [outputs]

            for out in outputs:
                text = str(out.get("text", "")).strip()
                non_empty += bool(text)

                if "language" in out and out["language"]:
                    language_found += 1
                else:
                    chunks = out.get("chunks") or []
                    langs = [
                        c.get("language")
                        for c in chunks
                        if isinstance(c, dict) and c.get("language")
                    ]
                    language_found += bool(langs)

        except Exception as e:
            errors += len(batch_paths)
            print("Batch failed:", start, start + len(batch_paths), repr(e), flush=True)

        done += len(batch_paths)

        elapsed = time.perf_counter() - t0
        fps = done / elapsed if elapsed > 0 else 0.0
        eta = (len(paths) - done) / fps if fps > 0 else 0.0

        print(
            f"[{done}/{len(paths)}] "
            f"elapsed={elapsed:.1f}s "
            f"fps={fps:.3f} "
            f"eta={eta / 60:.1f}m "
            f"non_empty={non_empty} "
            f"language_found={language_found} "
            f"errors={errors}",
            flush=True,
        )

    torch.cuda.synchronize()
    wall = time.perf_counter() - t0

    return {
        "engine": "hf_pipeline",
        "files": len(paths),
        "wall_seconds": wall,
        "files_per_second": len(paths) / wall if wall > 0 else 0.0,
        "gpu_batch_size": gpu_batch_size,
        "outer_batch_size": outer_batch_size,
        "return_language": return_language,
        "return_timestamps": return_timestamps,
        "chunk_length_s": chunk_length_s,
        "non_empty": non_empty,
        "language_found": language_found,
        "errors": errors,
    }

hf_results = []

for bs in [16, 32, 48, 64, 96]:
    try:
        print("Running HF batch size:", bs, flush=True)

        out = benchmark_hf_batched(
            whisper_input_df,
            n=1000,
            gpu_batch_size=bs,
            outer_batch_size=512,
            return_language=False,
            return_timestamps=False,
            chunk_length_s=None,   # use None for short clips under 30 sec
        )

        print(out, flush=True)
        hf_results.append(out)

    except RuntimeError as e:
        print("Failed batch size:", bs, repr(e), flush=True)
        clear_cuda()

hf_bench_df = pd.DataFrame(hf_results).sort_values(
    "files_per_second",
    ascending=False,
)

display(hf_bench_df)

best_hf = hf_bench_df.iloc[0]
print("Best HF raw config:", best_hf.to_dict())
print("Estimated full runtime hours:", len(whisper_input_df) / best_hf["files_per_second"] / 3600)

hf_lang_results = []

for bs in [16, 32, 48]:
    try:
        print("Running HF language batch size:", bs, flush=True)

        out = benchmark_hf_batched(
            whisper_input_df,
            n=500,
            gpu_batch_size=bs,
            outer_batch_size=256,
            return_language=True,
            return_timestamps=True,
            chunk_length_s=None,
        )

        print(out, flush=True)
        hf_lang_results.append(out)

    except Exception as e:
        print("Failed language batch size:", bs, repr(e), flush=True)
        clear_cuda()

hf_lang_bench_df = pd.DataFrame(hf_lang_results).sort_values(
    "files_per_second",
    ascending=False,
)

display(hf_lang_bench_df)

