import gc
import torch
from pathlib import Path
from transformers import AutoModelForSpeechSeq2Seq, AutoProcessor, pipeline


def clear_cuda():
    gc.collect()
    if torch.cuda.is_available():
        torch.cuda.empty_cache()
        torch.cuda.ipc_collect()


# Use a local HF-format folder if you already have one.
# This folder should contain files like config.json, generation_config.json,
# tokenizer.json, preprocessor_config.json, and model.safetensors shards.
HF_LARGE_V3_LOCAL = Path("/mnt/amc-data/pipeline/models/openai-whisper-large-v3-hf")

if HF_LARGE_V3_LOCAL.exists():
    HF_QUALITY_MODEL = str(HF_LARGE_V3_LOCAL)
