import time
import pandas as pd


def benchmark_hf_quality(
    df: pd.DataFrame,
    n: int = 1000,
    gpu_batch_size: int = 16,
    outer_batch_size: int = 256,
):
    sample_df = df.sample(
        n=min(n, len(df)),
        random_state=42,
    ).reset_index(drop=True)

    paths = sample_df["audio_filepath"].astype(str).tolist()

    print("=" * 80, flush=True)
    print("HF Whisper large-v3 quality benchmark", flush=True)
    print("files:", len(paths), flush=True)
    print("gpu_batch_size:", gpu_batch_size, flush=True)
    print("outer_batch_size:", outer_batch_size, flush=True)
    print("generate_kwargs:", QUALITY_GENERATE_KWARGS, flush=True)
    print("=" * 80, flush=True)

    # Warmup.
    warmup_paths = paths[:min(len(paths), gpu_batch_size)]

    _ = hf_asr(
        warmup_paths,
        batch_size=gpu_batch_size,
        return_timestamps=False,
        generate_kwargs=QUALITY_GENERATE_KWARGS,
    )

    torch.cuda.synchronize()

    t0 = time.perf_counter()
    done = 0
    non_empty = 0
    errors = 0

    for start in range(0, len(paths), outer_batch_size):
        batch_paths = paths[start:start + outer_batch_size]

        try:
            outputs = hf_asr(
                batch_paths,
                batch_size=gpu_batch_size,
                return_timestamps=False,
                generate_kwargs=QUALITY_GENERATE_KWARGS,
            )

            if isinstance(outputs, dict):
                outputs = [outputs]

            non_empty += sum(
                bool(str(o.get("text", "")).strip())
                for o in outputs
            )

        except Exception as e:
            errors += len(batch_paths)
            print("Batch failed:", start, start + len(batch_paths), repr(e), flush=True)
            clear_cuda()

        done += len(batch_paths)

        elapsed = time.perf_counter() - t0
        fps = done / elapsed if elapsed > 0 else 0.0
        eta = (len(paths) - done) / fps if fps > 0 else 0.0

        print(
            f"[{done}/{len(paths)}] "
            f"elapsed={elapsed:.1f}s "
            f"fps={fps:.3f} "
            f"eta={eta / 60:.1f}m "
            f"non_empty={non_empty} "
            f"errors={errors}",
            flush=True,
        )

    torch.cuda.synchronize()
    wall = time.perf_counter() - t0

    return {
        "engine": "hf_pipeline",
        "model": HF_QUALITY_MODEL,
        "files": len(paths),
        "wall_seconds": wall,
        "files_per_second": len(paths) / wall if wall > 0 else 0.0,
        "gpu_batch_size": gpu_batch_size,
        "outer_batch_size": outer_batch_size,
        "generate_kwargs": str(QUALITY_GENERATE_KWARGS),
        "non_empty": non_empty,
        "errors": errors,
    }


quality_results = []

for bs in [8, 16, 24, 32, 48, 64]:
    try:
        print("Running quality batch size:", bs, flush=True)

        out = benchmark_hf_quality(
            whisper_input_df,
            n=1000,
            gpu_batch_size=bs,
            outer_batch_size=256,
        )

        print(out, flush=True)
        quality_results.append(out)

    except RuntimeError as e:
        print("Failed batch size:", bs, repr(e), flush=True)
        clear_cuda()

quality_bench_df = pd.DataFrame(quality_results).sort_values(
    "files_per_second",
    ascending=False,
)

display(quality_bench_df)

best_quality = quality_bench_df.iloc[0]
print("Best quality config:", best_quality.to_dict())
print(
    "Estimated full runtime hours:",
    len(whisper_input_df) / best_quality["files_per_second"] / 3600,
)

