import gc
import os
import sys
import torch


def cuda_mem_report(label=""):
    if not torch.cuda.is_available():
        print(f"{label} CUDA not available")
        return

    torch.cuda.synchronize()

    free_b, total_b = torch.cuda.mem_get_info()
    allocated_b = torch.cuda.memory_allocated()
    reserved_b = torch.cuda.memory_reserved()
    max_allocated_b = torch.cuda.max_memory_allocated()
    max_reserved_b = torch.cuda.max_memory_reserved()

    gb = 1024 ** 3

    print("=" * 80, flush=True)
    print(label, flush=True)
    print(f"free:          {free_b / gb:.2f} GiB", flush=True)
    print(f"total:         {total_b / gb:.2f} GiB", flush=True)
    print(f"allocated:     {allocated_b / gb:.2f} GiB", flush=True)
    print(f"reserved:      {reserved_b / gb:.2f} GiB", flush=True)
    print(f"max_allocated: {max_allocated_b / gb:.2f} GiB", flush=True)
    print(f"max_reserved:  {max_reserved_b / gb:.2f} GiB", flush=True)
    print("=" * 80, flush=True)


def clear_cuda_hard(extra_names=None, verbose=True):
    """
    Aggressive cleanup for Jupyter.

    This only frees objects that are no longer referenced.
    It cannot free the loaded model unless you delete hf_asr and hf_model.
    """

    if extra_names is None:
        extra_names = []

    names_to_delete = [
        "outputs",
        "batch_outputs",
        "output",
        "out",
        "inputs",
        "input_features",
        "generated_ids",
        "batch",
        "batch_paths",
        "batch_df",
        "warmup_outputs",
        "warmup_paths",
    ] + list(extra_names)

    for name in names_to_delete:
        if name in globals():
            try:
                del globals()[name]
            except Exception:
                pass

    # Clear IPython last-output references.
    for name in ["_", "__", "___"]:
        if name in globals():
            try:
                del globals()[name]
            except Exception:
                pass

    # Clear Python's last exception references, which can hold tensors alive after OOM.
    for name in ["last_type", "last_value", "last_traceback"]:
        if hasattr(sys, name):
            try:
                setattr(sys, name, None)
            except Exception:
                pass

    gc.collect()

    if torch.cuda.is_available():
        try:
            torch.cuda.synchronize()
        except Exception:
            pass

        torch.cuda.empty_cache()
        torch.cuda.ipc_collect()

        gc.collect()

        torch.cuda.empty_cache()

        try:
            torch.cuda.reset_peak_memory_stats()
            torch.cuda.reset_accumulated_memory_stats()
        except Exception:
            pass

        try:
            torch.cuda.synchronize()
        except Exception:
            pass

    if verbose:
        cuda_mem_report("after clear_cuda_hard")

def unload_hf_asr(verbose=True):
    """
    Fully unload HF ASR pipeline and model from GPU.
    Run this before switching models or after an OOM benchmark.
    """

    names = [
        "hf_asr",
        "hf_model",
        "processor",
        "model",
        "asr_pipe",
        "tokenizer",
        "feature_extractor",
    ]

    for name in names:
        if name in globals():
            try:
                del globals()[name]
            except Exception:
                pass

    clear_cuda_hard(verbose=verbose)

