def hf_asr_call(paths, batch_size):
    with torch.inference_mode():
        outputs = hf_asr(
            paths,
            batch_size=batch_size,
            return_timestamps=False,
            generate_kwargs=QUALITY_GENERATE_KWARGS,
        )

    if isinstance(outputs, dict):
        outputs = [outputs]

    return outputs


def hf_transcribe_batch_safe(paths, batch_size):
    try:
        outputs = hf_asr_call(paths, batch_size=batch_size)

        result = [
            {
                "text": str(o.get("text", "")).strip(),
                "error": None,
            }
            for o in outputs
        ]

        del outputs
        clear_cuda_hard(verbose=False)

        return result

    except torch.cuda.OutOfMemoryError as e:
        print(
            f"OOM at batch_size={batch_size}, paths={len(paths)}. "
            f"Retrying smaller batch.",
            flush=True,
        )

        clear_cuda_hard(verbose=True)

        if len(paths) == 1 or batch_size <= 1:
            return [
                {
                    "text": "",
                    "error": repr(e),
                }
            ]

        mid = len(paths) // 2

        left = hf_transcribe_batch_safe(
            paths[:mid],
            batch_size=max(1, min(batch_size // 2, len(paths[:mid]))),
        )

        right = hf_transcribe_batch_safe(
            paths[mid:],
            batch_size=max(1, min(batch_size // 2, len(paths[mid:]))),
        )

        return left + right

    except Exception as e:
        clear_cuda_hard(verbose=True)

        if len(paths) == 1:
            return [
                {
                    "text": "",
                    "error": repr(e),
                }
            ]

        mid = len(paths) // 2

        left = hf_transcribe_batch_safe(
            paths[:mid],
            batch_size=max(1, min(batch_size // 2, len(paths[:mid]))),
        )

        right = hf_transcribe_batch_safe(
            paths[mid:],
            batch_size=max(1, min(batch_size // 2, len(paths[mid:]))),
        )

        return left + right

