import shutil
import time
import pandas as pd
from pathlib import Path


QUALITY_OUTPUT_DIR = CHECKPOINT_DIR / "hf_whisper_large_v3_beam5_quality_parts_clean"

# Start from beginning.
if QUALITY_OUTPUT_DIR.exists():
    shutil.rmtree(QUALITY_OUTPUT_DIR)

QUALITY_OUTPUT_DIR.mkdir(parents=True, exist_ok=True)

print("Output dir:", QUALITY_OUTPUT_DIR)

def run_hf_whisper_quality_production_clean(
    input_df: pd.DataFrame,
    output_dir: Path,
    outer_batch_size: int = 128,
    gpu_batch_size: int = 8,
    max_batch_error_rate: float = 0.02,
):
    output_dir.mkdir(parents=True, exist_ok=True)

    work_df = input_df.copy()
    work_df["segment_id"] = work_df["segment_id"].astype(str)
    work_df["audio_filepath"] = work_df["audio_filepath"].astype(str)
    work_df = work_df.reset_index(drop=True)

    print("Rows:", len(work_df), flush=True)
    print("gpu_batch_size:", gpu_batch_size, flush=True)
    print("outer_batch_size:", outer_batch_size, flush=True)
    print("generate_kwargs:", QUALITY_GENERATE_KWARGS, flush=True)

    # Preflight.
    preflight_df = work_df.head(min(16, len(work_df))).copy()
    preflight_paths = preflight_df["audio_filepath"].tolist()

    print("Preflight started...", flush=True)

    preflight_outputs = hf_transcribe_batch_safe(
        preflight_paths,
        batch_size=min(gpu_batch_size, len(preflight_paths)),
    )

    preflight_errors = sum(x["error"] is not None for x in preflight_outputs)

    if preflight_errors > 0:
        print(preflight_outputs[:5], flush=True)
        raise RuntimeError(
            f"Preflight failed with {preflight_errors}/{len(preflight_outputs)} errors."
        )

    print("Preflight passed.", flush=True)

    part_id = 0
    total_done = 0
    t0 = time.perf_counter()

    for start in range(0, len(work_df), outer_batch_size):
        batch_df = work_df.iloc[start:start + outer_batch_size].copy()
        paths = batch_df["audio_filepath"].tolist()

        batch_t0 = time.perf_counter()

        batch_outputs = hf_transcribe_batch_safe(
            paths,
            batch_size=gpu_batch_size,
        )

        if len(batch_outputs) != len(batch_df):
            raise RuntimeError(
                f"Output length mismatch: got {len(batch_outputs)}, expected {len(batch_df)}"
            )

        out_df = batch_df.copy()
        out_df["whisper_transcript"] = [x["text"] for x in batch_outputs]
        out_df["whisper_lang"] = FORCE_LANGUAGE
        out_df["whisper_conf"] = None
        out_df["whisper_duration_after_vad"] = None
        out_df["whisper_error"] = [x["error"] for x in batch_outputs]

        batch_errors = int(out_df["whisper_error"].notna().sum())
        batch_error_rate = batch_errors / max(1, len(out_df))

        if batch_error_rate > max_batch_error_rate:
            print(out_df[["segment_id", "audio_filepath", "whisper_error"]].head(20))
            raise RuntimeError(
                f"High batch error rate: {batch_errors}/{len(out_df)} "
                f"= {batch_error_rate:.2%}. Refusing to checkpoint."
            )

        output_path = output_dir / f"part_{part_id:06d}.parquet"
        out_df.to_parquet(output_path, index=False)

        del batch_outputs
        del out_df
        del batch_df
        clear_cuda_hard(verbose=False)

        part_id += 1
        total_done += len(paths)

        elapsed = time.perf_counter() - t0
        fps = total_done / elapsed if elapsed > 0 else 0.0
        eta_seconds = (len(work_df) - total_done) / fps if fps > 0 else 0.0
        batch_wall = time.perf_counter() - batch_t0

        print(
            f"[{total_done}/{len(work_df)}] "
            f"part={output_path.name} "
            f"batch_wall={batch_wall:.1f}s "
            f"fps={fps:.3f} "
            f"eta={eta_seconds / 3600:.2f}h "
            f"errors={batch_errors}",
            flush=True,
        )

    print("Done.", flush=True)

