# =========================================================
# COHERE TRANSCRIBE - FAST BATCHED VERSION
# Uses the same correct model class that worked for you.
# =========================================================

import os
import warnings
import torch
import pandas as pd
import numpy as np
from pathlib import Path
from typing import List
from concurrent.futures import ThreadPoolExecutor
from transformers import AutoProcessor, CohereAsrForConditionalGeneration
from transformers import logging as hf_logging

# -----------------------------
# CONFIG
# -----------------------------

RESET_COHERE_CHECKPOINT = True   # True only if checkpoint is bad
COHERE_BATCH_SIZE = 128             # start with 8; then try 16, 24, 32
COHERE_MAX_NEW_TOKENS = 256
COHERE_SR = 16000

# Keep float32 first because this is what already worked.
# After this is verified, you can try torch.bfloat16.
COHERE_TORCH_DTYPE = torch.float32

# Fix very short clips that can break batched encoder shapes.
# 0.50 sec is enough for the 32-frame encoder block issue.
COHERE_MIN_AUDIO_SEC = 0.50
COHERE_MIN_AUDIO_SAMPLES = int(COHERE_SR * COHERE_MIN_AUDIO_SEC)

# CPU audio loading workers. Use 2 to 8.
COHERE_LOAD_WORKERS = 8

cohere_ckpt_path = CHECKPOINT_DIR / "asr_cohere_transcribe_03_2026_local.csv"

if RESET_COHERE_CHECKPOINT and cohere_ckpt_path.exists():
    cohere_ckpt_path.unlink()
    print("Deleted old/bad Cohere checkpoint:", cohere_ckpt_path)

if ENABLE_COHERE and len(asr_run_df) > 0:
    os.environ["TRANSFORMERS_VERBOSITY"] = "error"
    hf_logging.set_verbosity_error()
    warnings.filterwarnings("ignore")

    clear_cuda()

    torch.backends.cuda.matmul.allow_tf32 = True
    torch.backends.cudnn.allow_tf32 = True

    cohere_processor = AutoProcessor.from_pretrained(
        str(COHERE_MODEL_DIR),
        local_files_only=True,
    )

    cohere_model = CohereAsrForConditionalGeneration.from_pretrained(
        str(COHERE_MODEL_DIR),
        device_map="auto" if torch.cuda.is_available() else None,
        torch_dtype=COHERE_TORCH_DTYPE,
        local_files_only=True,
    )

    cohere_model.eval()

    try:
        cohere_device = cohere_model.device
    except Exception:
        cohere_device = next(cohere_model.parameters()).device

    try:
        cohere_dtype = cohere_model.dtype
    except Exception:
        cohere_dtype = next(cohere_model.parameters()).dtype

    print("Loaded Cohere model from:", COHERE_MODEL_DIR)
    print("device:", cohere_device)
    print("dtype:", cohere_dtype)
    print("model batch size:", COHERE_BATCH_SIZE)
    print("max_new_tokens:", COHERE_MAX_NEW_TOKENS)
    print("min audio samples:", COHERE_MIN_AUDIO_SAMPLES)

    # For first optimized run, keep original order.
    # Sorting by duration can be faster later, but it can also group all tiny clips together.
    cohere_input_df = asr_run_df.copy().reset_index(drop=True)

    # -----------------------------
    # AUDIO LOADING
    # -----------------------------

    def _load_cohere_audio(path: str):
        path = Path(path)

        # Match your working path first.
        if "load_audio_mono" in globals():
            audio = load_audio_mono(path, sr=COHERE_SR)
        else:
            audio = load_audio_mono_np(path, sr=COHERE_SR)

        if torch.is_tensor(audio):
            audio = audio.detach().cpu().numpy()

        audio = np.asarray(audio, dtype=np.float32).reshape(-1)
        audio = np.nan_to_num(audio, nan=0.0, posinf=0.0, neginf=0.0)

        if audio.size == 0:
            audio = np.zeros(COHERE_MIN_AUDIO_SAMPLES, dtype=np.float32)

        if audio.size < COHERE_MIN_AUDIO_SAMPLES:
            audio = np.pad(
                audio,
                (0, COHERE_MIN_AUDIO_SAMPLES - audio.size),
                mode="constant",
                constant_values=0.0,
            )

        return audio

    audio_pool = ThreadPoolExecutor(max_workers=COHERE_LOAD_WORKERS)

    # -----------------------------
    # DECODE
    # -----------------------------

    def _decode_cohere(outputs, audio_chunk_index=None):
        try:
            decoded = cohere_processor.decode(
                outputs,
                skip_special_tokens=True,
                audio_chunk_index=audio_chunk_index,
                language="en",
            )
        except TypeError:
            decoded = cohere_processor.decode(
                outputs,
                skip_special_tokens=True,
            )

        if isinstance(decoded, str):
            return [decoded.strip()]

        if isinstance(decoded, list):
            return [str(x).strip() for x in decoded]

        return [str(decoded).strip()]

    # -----------------------------
    # SINGLE FALLBACK
    # -----------------------------

    def transcribe_cohere_single(path: str):
        try:
            audio = _load_cohere_audio(path)

            inputs = cohere_processor(
                audio,
                sampling_rate=COHERE_SR,
                return_tensors="pt",
                language="en",
                punctuation=False,
            )

            audio_chunk_index = inputs.get("audio_chunk_index", None)
            if torch.is_tensor(audio_chunk_index):
                audio_chunk_index_for_decode = audio_chunk_index.detach().cpu().clone()
            else:
                audio_chunk_index_for_decode = audio_chunk_index

            # Match your working code.
            inputs.to(cohere_device, dtype=cohere_dtype)

            with torch.inference_mode():
                outputs = cohere_model.generate(
                    **inputs,
                    max_new_tokens=COHERE_MAX_NEW_TOKENS,
                )

            texts = _decode_cohere(
                outputs,
                audio_chunk_index=audio_chunk_index_for_decode,
            )

            return texts[0] if len(texts) > 0 else "", None

        except Exception as e:
            return "", repr(e)

    # -----------------------------
    # TRUE BATCHED TRANSCRIPTION
    # -----------------------------

    def transcribe_cohere_batch(paths: List[str]):
        paths = [str(p) for p in paths]

        try:
            audios = list(audio_pool.map(_load_cohere_audio, paths))

            # Official batched path:
            # processor([audio1, audio2, ...])
            inputs = cohere_processor(
                audios,
                sampling_rate=COHERE_SR,
                return_tensors="pt",
                language="en",
                punctuation=False,
            )

            audio_chunk_index = inputs.get("audio_chunk_index", None)
            if torch.is_tensor(audio_chunk_index):
                audio_chunk_index_for_decode = audio_chunk_index.detach().cpu().clone()
            else:
                audio_chunk_index_for_decode = audio_chunk_index

            # Match your working code path.
            inputs.to(cohere_device, dtype=cohere_dtype)

            with torch.inference_mode():
                outputs = cohere_model.generate(
                    **inputs,
                    max_new_tokens=COHERE_MAX_NEW_TOKENS,
                )

            texts = _decode_cohere(
                outputs,
                audio_chunk_index=audio_chunk_index_for_decode,
            )

            if len(texts) != len(paths):
                texts = texts[:len(paths)] + [""] * max(0, len(paths) - len(texts))
                errors = ["BAD_OUTPUT_LENGTH"] * len(paths)
            else:
                errors = [None] * len(paths)

            return texts, errors

        except torch.cuda.OutOfMemoryError:
            torch.cuda.empty_cache()

            # Split the batch instead of losing it.
            if len(paths) > 1:
                mid = len(paths) // 2
                t1, e1 = transcribe_cohere_batch(paths[:mid])
                t2, e2 = transcribe_cohere_batch(paths[mid:])
                return t1 + t2, e1 + e2

            return [""], ["CUDA_OUT_OF_MEMORY"]

        except Exception as batch_e:
            # If a batched call fails, split recursively.
            # This preserves speed for normal batches and correctness for weird files.
            if len(paths) > 1:
                mid = len(paths) // 2
                t1, e1 = transcribe_cohere_batch(paths[:mid])
                t2, e2 = transcribe_cohere_batch(paths[mid:])
                return t1 + t2, e1 + e2

            text, err = transcribe_cohere_single(paths[0])
            return [text], [err]

    # -----------------------------
    # PREFLIGHT
    # -----------------------------

    print("Running Cohere batched preflight...")

    preflight_parts = [cohere_input_df.head(COHERE_BATCH_SIZE)]

    if "duration" in cohere_input_df.columns:
        tmp_short = cohere_input_df.copy()
        tmp_short["duration"] = pd.to_numeric(tmp_short["duration"], errors="coerce")
        preflight_parts.append(tmp_short.sort_values("duration").head(COHERE_BATCH_SIZE))

    if len(cohere_input_df) > COHERE_BATCH_SIZE:
        preflight_parts.append(
            cohere_input_df.sample(
                n=min(COHERE_BATCH_SIZE, len(cohere_input_df)),
                random_state=42,
            )
        )

    preflight_df = (
        pd.concat(preflight_parts, ignore_index=True)
        .drop_duplicates("segment_id")
        .head(max(16, COHERE_BATCH_SIZE))
        .reset_index(drop=True)
    )

    preflight_texts, preflight_errors = transcribe_cohere_batch(
        preflight_df["audio_filepath"].astype(str).tolist()
    )

    preflight_out = preflight_df[["segment_id", "audio_filepath"]].copy()
    if "duration" in preflight_df.columns:
        preflight_out["duration"] = preflight_df["duration"].values

    preflight_out["cohere_transcript"] = preflight_texts
    preflight_out["cohere_error"] = preflight_errors

    print("Preflight rows:", len(preflight_out))
    print("Preflight non-empty:", pd.Series(preflight_texts).fillna("").astype(str).str.strip().ne("").sum())
    print("Preflight errors:", pd.Series(preflight_errors).notna().sum())
    display(preflight_out.head(20))

    if any(e is not None for e in preflight_errors):
        print(pd.Series(preflight_errors).value_counts(dropna=False).head(20))
        raise RuntimeError("Cohere batched preflight failed. Do not run full data.")

    # -----------------------------
    # FULL RUN
    # -----------------------------

    cohere_df = run_batch_engine(
        cohere_input_df,
        transcribe_cohere_batch,
        output_col="cohere_transcript",
        error_col="cohere_error",
        output_path=cohere_ckpt_path,
        batch_size=COHERE_BATCH_SIZE,
        desc="Cohere Transcribe",
    )

    print("Cohere rows:", len(cohere_df))
    print("Cohere non-empty:", cohere_df["cohere_transcript"].fillna("").astype(str).str.strip().ne("").sum())
    print("Cohere errors:", cohere_df["cohere_error"].notna().sum())

    cohere_df["cohere_word_count"] = (
        cohere_df["cohere_transcript"]
        .fillna("")
        .astype(str)
        .str.split()
        .str.len()
    )

    print("Cohere word count stats:")
    print(cohere_df["cohere_word_count"].describe())
    display(cohere_df.head(20))

    audio_pool.shutdown(wait=False)

    del cohere_model
    del cohere_processor
    clear_cuda()

else:
    cohere_df = pd.DataFrame({
        "segment_id": asr_run_df["segment_id"],
        "cohere_transcript": "",
        "cohere_error": None,
    })

# =========================================================
# COHERE PARTIAL RUN QC
# =========================================================

import pandas as pd
import numpy as np
from pathlib import Path
from difflib import SequenceMatcher

cohere_ckpt_path = CHECKPOINT_DIR / "asr_cohere_transcribe_03_2026_local.csv"

tmp = pd.read_csv(cohere_ckpt_path)

tmp["cohere_transcript"] = (
    tmp["cohere_transcript"]
    .fillna("")
    .astype(str)
    .str.strip()
)

print("checkpoint:", cohere_ckpt_path)
print("rows:", len(tmp))
print("unique segment_id:", tmp["segment_id"].nunique())
print("duplicate segment_id:", tmp["segment_id"].duplicated().sum())
print("non-empty:", tmp["cohere_transcript"].ne("").sum())
print("errors:", tmp["cohere_error"].notna().sum())

print("\nTop errors:")
print(tmp["cohere_error"].value_counts(dropna=False).head(20))

tmp["word_count"] = tmp["cohere_transcript"].str.split().str.len()
tmp["char_count"] = tmp["cohere_transcript"].str.len()

# CJK/Hangul garbage check
tmp["cjk_count"] = tmp["cohere_transcript"].str.count(r"[\u4e00-\u9fff\u3040-\u30ff\uac00-\ud7af]")
tmp["has_cjk"] = tmp["cjk_count"] > 0

# Non-ASCII ratio check
tmp["non_ascii_count"] = tmp["cohere_transcript"].apply(lambda s: sum(ord(ch) > 127 for ch in s))
tmp["non_ascii_ratio"] = tmp["non_ascii_count"] / tmp["char_count"].replace(0, np.nan)

# Repeated transcript check
tmp["repeat_count"] = tmp.groupby("cohere_transcript")["segment_id"].transform("count")
tmp["suspicious_repeat"] = (
    (tmp["cohere_transcript"].str.len() >= 12)
    & (tmp["repeat_count"] >= 20)
)

print("\nWord count stats:")
print(tmp["word_count"].describe())

print("\nCJK/Hangul rows:", int(tmp["has_cjk"].sum()))
print("Suspicious repeated transcript rows:", int(tmp["suspicious_repeat"].sum()))

print("\nTop repeated transcripts:")
display(
    tmp["cohere_transcript"]
    .value_counts()
    .head(30)
    .rename_axis("transcript")
    .reset_index(name="count")
)

# =========================================================
# MERGE COHERE PARTIAL WITH ASR METADATA
# =========================================================

meta_cols = ["segment_id"]

for c in [
    "audio_filepath",
    "duration",
    "usable_speech_sec",
    "call_id",
    "channel_idx",
    "start_sample",
    "whisper_transcript",
    "whisper_lang",
    "whisper_conf",
]:
    if c in asr_run_df.columns:
        meta_cols.append(c)

qc = tmp.merge(
    asr_run_df[meta_cols],
    on="segment_id",
    how="left",
)

print("merged rows:", len(qc))
print("missing audio_filepath:", qc["audio_filepath"].isna().sum() if "audio_filepath" in qc.columns else "no audio_filepath column")

if "duration" in qc.columns:
    qc["duration"] = pd.to_numeric(qc["duration"], errors="coerce")
    qc["words_per_sec"] = qc["word_count"] / qc["duration"].clip(lower=0.1)

    qc["too_many_words_for_short_audio"] = (
        (qc["duration"] <= 2.0)
        & (qc["word_count"] >= 14)
    )

    qc["too_few_words_for_long_audio"] = (
        (qc["duration"] >= 8.0)
        & (qc["word_count"] <= 1)
    )

    print("\nWords/sec stats:")
    print(qc["words_per_sec"].describe())

    print("too many words for short audio:", int(qc["too_many_words_for_short_audio"].sum()))
    print("too few words for long audio:", int(qc["too_few_words_for_long_audio"].sum()))

# =========================================================
# ROUGH COHERE VS WHISPER CHECK
# =========================================================

if "whisper_transcript" in qc.columns:
    qc["whisper_transcript"] = (
        qc["whisper_transcript"]
        .fillna("")
        .astype(str)
        .str.strip()
    )

    def text_sim(a, b):
        a = str(a).lower().strip()
        b = str(b).lower().strip()
        if not a and not b:
            return np.nan
        if not a or not b:
            return 0.0
        return SequenceMatcher(None, a, b).ratio()

    qc["cohere_whisper_similarity"] = [
        text_sim(a, b)
        for a, b in zip(qc["cohere_transcript"], qc["whisper_transcript"])
    ]

    print("Cohere vs Whisper similarity:")
    print(qc["cohere_whisper_similarity"].describe())

    cols = [
        "segment_id",
        "duration" if "duration" in qc.columns else None,
        "whisper_conf" if "whisper_conf" in qc.columns else None,
        "cohere_whisper_similarity",
        "whisper_transcript",
        "cohere_transcript",
        "cohere_error",
    ]
    cols = [c for c in cols if c is not None and c in qc.columns]

    print("\nLowest similarity examples:")
    display(
        qc.sort_values("cohere_whisper_similarity", na_position="last")[cols].head(30)
    )

# =========================================================
# GRANITE SPEECH - CORRECT OFFICIAL PROCESSOR PATH
# =========================================================
# Fixes:
# 1. Deletes bad prompt-echo checkpoint
# 2. Uses official positional processor call: processor(prompt, wav, ...)
# 3. Decodes only generated tokens after input_ids length
# 4. Blocks full run if preflight returns prompt echo
# 5. Uses true batched inference only if direct batch preflight passes
# =========================================================

import os
import warnings
import torch
import pandas as pd
import numpy as np
from pathlib import Path
from typing import List
from concurrent.futures import ThreadPoolExecutor
from transformers import AutoProcessor, AutoModelForSpeechSeq2Seq
from transformers import logging as hf_logging

# -----------------------------
# CONFIG
# -----------------------------

RESET_GRANITE_CHECKPOINT = False       # keep True now because current checkpoint is bad
GRANITE_BATCH_SIZE = 128                # start safe; try 16 only after QC passes
GRANITE_MAX_NEW_TOKENS = 400
GRANITE_LOAD_WORKERS = 4
GRANITE_SR = 16000

granite_ckpt_path = CHECKPOINT_DIR / "asr_granite_4_0_1b_speech_local.csv"

if RESET_GRANITE_CHECKPOINT and granite_ckpt_path.exists():
    granite_ckpt_path.unlink()
    print("Deleted old/bad Granite checkpoint:", granite_ckpt_path)

if ENABLE_GRANITE and len(asr_run_df) > 0:
    os.environ["TRANSFORMERS_VERBOSITY"] = "error"
    hf_logging.set_verbosity_error()
    warnings.filterwarnings("ignore")

    clear_cuda()

    torch.backends.cuda.matmul.allow_tf32 = True
    torch.backends.cudnn.allow_tf32 = True

    granite_device_str = "cuda" if torch.cuda.is_available() else "cpu"
    granite_torch_dtype = torch.bfloat16 if torch.cuda.is_available() else torch.float32

    # -----------------------------
    # LOAD MODEL
    # -----------------------------

    granite_processor = AutoProcessor.from_pretrained(
        str(GRANITE_MODEL_DIR),
        local_files_only=True,
        trust_remote_code=True,
    )

    granite_tokenizer = getattr(granite_processor, "tokenizer", None)

    granite_model = AutoModelForSpeechSeq2Seq.from_pretrained(
        str(GRANITE_MODEL_DIR),
        device_map=granite_device_str if torch.cuda.is_available() else None,
        torch_dtype=granite_torch_dtype,
        local_files_only=True,
        trust_remote_code=True,
    )

    granite_model.eval()

    try:
        granite_device = granite_model.device
    except Exception:
        granite_device = next(granite_model.parameters()).device

    granite_dtype = next(granite_model.parameters()).dtype

    if granite_tokenizer is not None:
        if getattr(granite_tokenizer, "pad_token_id", None) is None:
            granite_tokenizer.pad_token_id = granite_tokenizer.eos_token_id

    print("Loaded Granite from:", GRANITE_MODEL_DIR)
    print("device:", granite_device)
    print("dtype:", granite_dtype)
    print("batch size:", GRANITE_BATCH_SIZE)
    print("max_new_tokens:", GRANITE_MAX_NEW_TOKENS)

    # -----------------------------
    # INPUT ORDER
    # -----------------------------

    granite_input_df = asr_run_df.copy()

    duration_col = None
    for c in ["duration", "duration_sec", "segment_duration", "seg_duration", "usable_speech_sec"]:
        if c in granite_input_df.columns:
            duration_col = c
            break

    if duration_col is not None:
        granite_input_df[duration_col] = pd.to_numeric(
            granite_input_df[duration_col],
            errors="coerce",
        )
        granite_input_df = granite_input_df.sort_values(duration_col).reset_index(drop=True)
        print("Sorted Granite input by duration column:", duration_col)
    else:
        granite_input_df = granite_input_df.reset_index(drop=True)
        print("No duration column found. Running in existing order.")

    # -----------------------------
    # PROMPT
    # -----------------------------

    def build_granite_prompt():
        user_prompt = "<|audio|>can you transcribe the speech into a written format?"

        if granite_tokenizer is not None and hasattr(granite_tokenizer, "apply_chat_template"):
            chat = [{"role": "user", "content": user_prompt}]
            return granite_tokenizer.apply_chat_template(
                chat,
                tokenize=False,
                add_generation_prompt=True,
            )

        return user_prompt

    GRANITE_PROMPT = build_granite_prompt()

    print("Prompt preview:")
    print(GRANITE_PROMPT[:300])

    # -----------------------------
    # HELPERS
    # -----------------------------

    def load_granite_audio(path: str):
        """
        Granite expects mono 16k audio.
        Return shape [1, T], matching official example.
        """
        wav = load_wav_16k_mono_tensor(path)

        if torch.is_tensor(wav):
            wav = wav.detach().cpu().float()
        else:
            wav = torch.tensor(np.asarray(wav, dtype=np.float32), dtype=torch.float32)

        if wav.ndim == 1:
            wav = wav.unsqueeze(0)

        if wav.ndim == 2 and wav.shape[0] > 1:
            wav = wav.mean(dim=0, keepdim=True)

        wav = torch.nan_to_num(wav, nan=0.0, posinf=0.0, neginf=0.0)

        return wav

    def safe_move_inputs_to_device_dtype(inputs, device, dtype):
        """
        Move tensors to device.
        Cast only floating tensors.
        Never cast input_ids or masks to bf16.
        """
        for k, v in list(inputs.items()):
            if torch.is_tensor(v):
                if v.is_floating_point():
                    inputs[k] = v.to(device=device, dtype=dtype)
                else:
                    inputs[k] = v.to(device=device)
        return inputs

    def make_granite_inputs(prompts, wavs):
        """
        Official-style call:
            processor(prompt, wav, device=device, return_tensors="pt")
        For batches:
            processor([prompt,...], [wav,...], device=device, return_tensors="pt", padding=True)
        """
        model_inputs = granite_processor(
            prompts,
            wavs,
            device=granite_device_str,
            return_tensors="pt",
            padding=True,
        )

        model_inputs = safe_move_inputs_to_device_dtype(
            model_inputs,
            granite_device,
            granite_dtype,
        )

        return model_inputs

    def clean_granite_text(text: str):
        text = str(text).strip()

        for bad in [
            "<|end_of_text|>",
            "<|endoftext|>",
            "<|end|>",
        ]:
            text = text.replace(bad, "")

        return " ".join(text.strip().split())

    def decode_granite_generated_only(model_outputs, model_inputs):
        """
        Decode only generated tokens.
        Never decode the prompt.
        """
        if "input_ids" not in model_inputs:
            raise RuntimeError("Granite model_inputs missing input_ids. Cannot safely remove prompt tokens.")

        num_input_tokens = model_inputs["input_ids"].shape[-1]

        if model_outputs.shape[-1] <= num_input_tokens:
            return [""] * model_outputs.shape[0], ["NO_NEW_TOKENS_PROMPT_ONLY"] * model_outputs.shape[0]

        new_tokens = model_outputs[:, num_input_tokens:]

        decoder = granite_tokenizer if granite_tokenizer is not None else granite_processor

        decoded = decoder.batch_decode(
            new_tokens,
            add_special_tokens=False,
            skip_special_tokens=True,
        )

        texts = [clean_granite_text(x) for x in decoded]

        errors = []
        for text in texts:
            low = text.lower()

            if low.startswith("user:") or "can you transcribe the speech" in low:
                errors.append("PROMPT_ECHO")
            else:
                errors.append(None)

        return texts, errors

    audio_pool = ThreadPoolExecutor(max_workers=GRANITE_LOAD_WORKERS)

    # -----------------------------
    # DIRECT BATCH TRANSCRIPTION
    # -----------------------------

    def transcribe_granite_batch_no_fallback(paths: List[str]):
        paths = [str(p) for p in paths]

        wavs = list(audio_pool.map(load_granite_audio, paths))
        prompts = [GRANITE_PROMPT] * len(wavs)

        model_inputs = make_granite_inputs(prompts, wavs)

        generation_kwargs = {
            "max_new_tokens": GRANITE_MAX_NEW_TOKENS,
            "do_sample": False,
            "num_beams": 1,
        }

        if granite_tokenizer is not None and getattr(granite_tokenizer, "eos_token_id", None) is not None:
            generation_kwargs["eos_token_id"] = granite_tokenizer.eos_token_id

        if granite_tokenizer is not None and getattr(granite_tokenizer, "pad_token_id", None) is not None:
            generation_kwargs["pad_token_id"] = granite_tokenizer.pad_token_id

        with torch.inference_mode():
            model_outputs = granite_model.generate(
                **model_inputs,
                **generation_kwargs,
            )

        texts, errors = decode_granite_generated_only(model_outputs, model_inputs)

        if len(texts) != len(paths):
            texts = texts[:len(paths)] + [""] * max(0, len(paths) - len(texts))
            errors = ["BAD_OUTPUT_LENGTH"] * len(paths)

        return texts, errors

    # -----------------------------
    # SAFE RECURSIVE BATCH WRAPPER
    # -----------------------------

    def transcribe_granite_batch(paths: List[str]):
        paths = [str(p) for p in paths]

        try:
            return transcribe_granite_batch_no_fallback(paths)

        except torch.cuda.OutOfMemoryError:
            torch.cuda.empty_cache()

            if len(paths) > 1:
                mid = len(paths) // 2
                t1, e1 = transcribe_granite_batch(paths[:mid])
                t2, e2 = transcribe_granite_batch(paths[mid:])
                return t1 + t2, e1 + e2

            return [""], ["CUDA_OUT_OF_MEMORY"]

        except Exception as batch_e:
            if len(paths) > 1:
                mid = len(paths) // 2
                t1, e1 = transcribe_granite_batch(paths[:mid])
                t2, e2 = transcribe_granite_batch(paths[mid:])
                return t1 + t2, e1 + e2

            try:
                return transcribe_granite_batch_no_fallback(paths)
            except Exception as single_e:
                return [""], [repr(single_e)]

    # -----------------------------
    # PREFLIGHT TEST
    # -----------------------------

    print("Running Granite direct-batch preflight...")

    preflight_parts = []

    preflight_parts.append(granite_input_df.head(GRANITE_BATCH_SIZE))

    if duration_col is not None:
        preflight_parts.append(granite_input_df.sort_values(duration_col).head(GRANITE_BATCH_SIZE))

    if len(granite_input_df) > GRANITE_BATCH_SIZE:
        preflight_parts.append(
            granite_input_df.sample(
                n=min(GRANITE_BATCH_SIZE, len(granite_input_df)),
                random_state=42,
            )
        )

    preflight_df = (
        pd.concat(preflight_parts, ignore_index=True)
        .drop_duplicates("segment_id")
        .head(max(16, GRANITE_BATCH_SIZE))
        .reset_index(drop=True)
    )

    # Important: no fallback here. This proves true batching works.
    preflight_texts, preflight_errors = transcribe_granite_batch_no_fallback(
        preflight_df["audio_filepath"].astype(str).tolist()
    )

    preflight_out = preflight_df[["segment_id", "audio_filepath"]].copy()

    if duration_col is not None and duration_col in preflight_df.columns:
        preflight_out[duration_col] = preflight_df[duration_col].values

    preflight_out["granite_transcript"] = preflight_texts
    preflight_out["granite_error"] = preflight_errors

    print("Preflight rows:", len(preflight_out))
    print("Preflight non-empty:", pd.Series(preflight_texts).fillna("").astype(str).str.strip().ne("").sum())
    print("Preflight errors:", pd.Series(preflight_errors).notna().sum())

    display(preflight_out.head(30))

    if any(e is not None for e in preflight_errors):
        print(pd.Series(preflight_errors).value_counts(dropna=False).head(20))
        raise RuntimeError("Granite preflight failed. Full run blocked.")

    prompt_echo_count = (
        preflight_out["granite_transcript"]
        .fillna("")
        .astype(str)
        .str.lower()
        .str.contains("can you transcribe the speech|user:")
        .sum()
    )

    if prompt_echo_count > 0:
        raise RuntimeError("Granite preflight returned prompt echo. Full run blocked.")

    # -----------------------------
    # FULL RUN
    # -----------------------------

    granite_df = run_batch_engine(
        granite_input_df,
        transcribe_granite_batch,
        output_col="granite_transcript",
        error_col="granite_error",
        output_path=granite_ckpt_path,
        batch_size=GRANITE_BATCH_SIZE,
        desc="Granite Speech",
    )

    print("Granite rows:", len(granite_df))
    print("Granite non-empty:", granite_df["granite_transcript"].fillna("").astype(str).str.strip().ne("").sum())
    print("Granite errors:", granite_df["granite_error"].notna().sum())

    granite_df["granite_word_count"] = (
        granite_df["granite_transcript"]
        .fillna("")
        .astype(str)
        .str.split()
        .str.len()
    )

    print("Granite word count stats:")
    print(granite_df["granite_word_count"].describe())

    display(granite_df.head(20))

    audio_pool.shutdown(wait=False)

    del granite_model
    del granite_processor

    try:
        del granite_tokenizer
    except Exception:
        pass

    clear_cuda()

else:
    granite_df = pd.DataFrame({
        "segment_id": asr_run_df["segment_id"],
        "granite_transcript": "",
        "granite_error": None,
    })

tmp = pd.read_csv(CHECKPOINT_DIR / "asr_granite_4_0_1b_speech_local.csv")

print("rows:", len(tmp))
print("non-empty:", tmp["granite_transcript"].fillna("").astype(str).str.strip().ne("").sum())
print("errors:", tmp["granite_error"].notna().sum())
print(tmp["granite_error"].value_counts(dropna=False).head(20))

display(tmp.head(20))

# =========================================================
# GRANITE CHECKPOINT QC
# =========================================================

import pandas as pd
import numpy as np
from difflib import SequenceMatcher

granite_ckpt_path = CHECKPOINT_DIR / "asr_granite_4_0_1b_speech_local.csv"

g = pd.read_csv(granite_ckpt_path)

g["granite_transcript"] = (
    g["granite_transcript"]
    .fillna("")
    .astype(str)
    .str.strip()
)

# Treat literal "None" as no error if it appears from CSV/string conversion
g["granite_error_clean"] = g["granite_error"]
g["granite_error_clean"] = g["granite_error_clean"].replace(
    {"None": np.nan, "nan": np.nan, "": np.nan}
)

print("rows:", len(g))
print("unique segment_id:", g["segment_id"].nunique())
print("duplicate segment_id:", g["segment_id"].duplicated().sum())
print("non-empty:", g["granite_transcript"].ne("").sum())
print("errors:", g["granite_error_clean"].notna().sum())

print("\nTop errors:")
print(g["granite_error_clean"].value_counts(dropna=False).head(20))

g["word_count"] = g["granite_transcript"].str.split().str.len()
g["char_count"] = g["granite_transcript"].str.len()

g["prompt_echo"] = (
    g["granite_transcript"]
    .str.lower()
    .str.contains("can you transcribe the speech|^user:", regex=True)
)

print("\nPrompt echo rows:", int(g["prompt_echo"].sum()))

print("\nWord count stats:")
print(g["word_count"].describe())

display(g.head(30))

# =========================================================
# MERGE GRANITE WITH ASR METADATA
# =========================================================

meta_cols = ["segment_id"]

for c in [
    "audio_filepath",
    "duration",
    "usable_speech_sec",
    "whisper_transcript",
    "whisper_conf",
    "whisper_lang",
]:
    if c in asr_run_df.columns:
        meta_cols.append(c)

qc = g.merge(
    asr_run_df[meta_cols],
    on="segment_id",
    how="left",
)

if "duration" in qc.columns:
    qc["duration"] = pd.to_numeric(qc["duration"], errors="coerce")
    qc["words_per_sec"] = qc["word_count"] / qc["duration"].clip(lower=0.1)

    print("Words/sec stats:")
    print(qc["words_per_sec"].describe())

    qc["too_short_for_long_audio"] = (
        (qc["duration"] >= 5.0)
        & (qc["word_count"] <= 2)
    )

    qc["too_many_words_for_short_audio"] = (
        (qc["duration"] <= 1.5)
        & (qc["word_count"] >= 12)
    )

    print("too_short_for_long_audio:", int(qc["too_short_for_long_audio"].sum()))
    print("too_many_words_for_short_audio:", int(qc["too_many_words_for_short_audio"].sum()))

# =========================================================
# GRANITE VS WHISPER LENGTH AND SIMILARITY CHECK
# =========================================================

if "whisper_transcript" in qc.columns:
    qc["whisper_transcript"] = (
        qc["whisper_transcript"]
        .fillna("")
        .astype(str)
        .str.strip()
    )

    qc["whisper_word_count"] = qc["whisper_transcript"].str.split().str.len()

    qc["granite_to_whisper_wc_ratio"] = (
        qc["word_count"] / qc["whisper_word_count"].replace(0, np.nan)
    )

    def sim(a, b):
        a = str(a).lower().strip()
        b = str(b).lower().strip()
        if not a and not b:
            return np.nan
        if not a or not b:
            return 0.0
        return SequenceMatcher(None, a, b).ratio()

    qc["granite_whisper_similarity"] = [
        sim(a, b)
        for a, b in zip(qc["granite_transcript"], qc["whisper_transcript"])
    ]

    qc["possible_cutoff_vs_whisper"] = (
        (qc["whisper_word_count"] >= 6)
        & (qc["granite_to_whisper_wc_ratio"] < 0.55)
        & (qc["whisper_conf"].fillna(0) >= 0.5)
    )

    print("Granite/Whisper word-count ratio:")
    print(qc["granite_to_whisper_wc_ratio"].describe())

    print("\nGranite/Whisper similarity:")
    print(qc["granite_whisper_similarity"].describe())

    print("\npossible_cutoff_vs_whisper:", int(qc["possible_cutoff_vs_whisper"].sum()))

    display(
        qc.sort_values("granite_to_whisper_wc_ratio")
        [[
            "segment_id",
            "duration",
            "whisper_conf",
            "whisper_word_count",
            "word_count",
            "granite_to_whisper_wc_ratio",
            "whisper_transcript",
            "granite_transcript",
            "audio_filepath",
        ]]
        .head(40)
    )



