display(asr_outputs_df.head())

# =========================================================
# TRANSCRIPT NORMALIZATION AND SIMILARITY
# =========================================================

_UNITS = {
    'zero': '0', 'one': '1', 'two': '2', 'three': '3', 'four': '4',
    'five': '5', 'six': '6', 'seven': '7', 'eight': '8', 'nine': '9',
}
_TEENS = {
    'ten': '10', 'eleven': '11', 'twelve': '12', 'thirteen': '13', 'fourteen': '14',
    'fifteen': '15', 'sixteen': '16', 'seventeen': '17', 'eighteen': '18', 'nineteen': '19',
}
_TENS = {
    'twenty': '20', 'thirty': '30', 'forty': '40', 'fifty': '50',
    'sixty': '60', 'seventy': '70', 'eighty': '80', 'ninety': '90',
}
_FILLERS = {'uh', 'um', 'erm', 'mm', 'mmm', 'mhmm', 'hmm', 'uhhuh', 'uh-huh', 'uhuh', 'ah', 'eh', 'aha', 'huh', 'hm'}
_CONTRACTIONS = {
    "i'm": 'i am', "you're": 'you are', "we're": 'we are', "they're": 'they are',
    "it's": 'it is', "that's": 'that is', "there's": 'there is', "what's": 'what is',
    "can't": 'cannot', "won't": 'will not', "don't": 'do not', "doesn't": 'does not',
    "didn't": 'did not', "isn't": 'is not', "aren't": 'are not', "wasn't": 'was not',
    "weren't": 'were not', "shouldn't": 'should not', "wouldn't": 'would not',
    "couldn't": 'could not', "i've": 'i have', "we've": 'we have', "they've": 'they have',
    "you've": 'you have', "i'll": 'i will', "you'll": 'you will', "we'll": 'we will',
    "they'll": 'they will', "i'd": 'i would', "you'd": 'you would', "we'd": 'we would',
    "they'd": 'they would', "let's": 'let us',
}
_EQUIV_SINGLE = {'alright': 'all right', 'allright': 'all right', 'ok': 'okay', 'k': 'okay', 'kay': 'okay'}
_PUNCT = "!\"#$%&'()*+,./:;<=>?@[\\]^_`{|}~“”’"


def cleanup_unicode_lower(s: str) -> str:
    s = unicodedata.normalize('NFKC', s or '')
    s = s.replace('’', "'").replace('‘', "'").replace('“', '"').replace('”', '"')
    s = s.lower()
    s = re.sub(r'(\d+)(st|nd|rd|th)', r'', s)
    return s


def expand_contractions(text: str) -> str:
    for k, v in _CONTRACTIONS.items():
        text = re.sub(rf'{re.escape(k)}', v, text)
    return text


def normalize_transcript(s: str, remove_fillers: bool = True) -> str:
    if s is None or pd.isna(s):
        return ''
    s = cleanup_unicode_lower(str(s))
    s = expand_contractions(s)
    s = s.replace('...', ' ')
    s = re.sub(f'[{re.escape(_PUNCT)}]', ' ', s)
    toks = re.findall(r'[a-z0-9]+', s)
    if remove_fillers:
        toks = [t for t in toks if t not in _FILLERS]

    out = []
    for t in toks:
        if t in _EQUIV_SINGLE:
            out.extend(_EQUIV_SINGLE[t].split())
        elif t in _UNITS:
            out.append(_UNITS[t])
        elif t in _TEENS:
            out.append(_TEENS[t])
        elif t in _TENS:
            out.append(_TENS[t])
        else:
            out.append(t)
    return re.sub(r'\s+', ' ', ' '.join(out)).strip()


def levenshtein_seq(a, b) -> int:
    if a == b:
        return 0
    if len(a) == 0:
        return len(b)
    if len(b) == 0:
        return len(a)
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        curr = [i]
        for j, cb in enumerate(b, 1):
            curr.append(min(curr[j - 1] + 1, prev[j] + 1, prev[j - 1] + (ca != cb)))
        prev = curr
    return prev[-1]


def cer(ref: str, hyp: str) -> float:
    ref = ref or ''
    hyp = hyp or ''
    if len(ref) == 0 and len(hyp) == 0:
        return 0.0
    if len(ref) == 0:
        return 1.0
    return levenshtein_seq(list(ref), list(hyp)) / len(ref)


def wer(ref: str, hyp: str) -> float:
    ref_words = (ref or '').split()
    hyp_words = (hyp or '').split()
    if len(ref_words) == 0 and len(hyp_words) == 0:
        return 0.0
    if len(ref_words) == 0:
        return 1.0
    return levenshtein_seq(ref_words, hyp_words) / len(ref_words)


def jaccard(a: str, b: str) -> float:
    sa = set((a or '').split())
    sb = set((b or '').split())
    if not sa and not sb:
        return 1.0
    union = sa | sb
    return len(sa & sb) / len(union) if union else 0.0


def combined_similarity(a: str, b: str) -> float:
    w = wer(a, b)
    c = cer(a, b)
    j = jaccard(a, b)
    word_sim = max(0.0, 1.0 - min(w, 1.0))
    char_sim = max(0.0, 1.0 - min(c, 1.0))
    return (0.55 * word_sim) + (0.25 * char_sim) + (0.20 * j)

# =========================================================
# CONSENSUS SELECTION
# =========================================================

TRANSCRIPT_COLS = {
    'whisper': 'whisper_transcript',
    'qwen': 'qwen_transcript',
    'cohere': 'cohere_transcript',
    'granite': 'granite_transcript',
}

# Keep only enabled model columns that exist.
TRANSCRIPT_COLS = {
    model: col for model, col in TRANSCRIPT_COLS.items()
    if col in asr_outputs_df.columns
}


def choose_raw_for_norm(model_texts: Dict[str, str], norm_target: str, preferred_models: Optional[List[str]] = None) -> Tuple[str, str]:
    candidates = []
    preferred_models = preferred_models or list(model_texts.keys())
    for model in preferred_models:
        raw = str(model_texts.get(model, '') or '').strip()
        if raw and normalize_transcript(raw) == norm_target:
            candidates.append((model, raw))
    if not candidates:
        for model, raw in model_texts.items():
            raw = str(raw or '').strip()
            if raw:
                candidates.append((model, raw))
    if not candidates:
        return '', ''
    # Prefer the longest raw form because it often preserves punctuation and words.
    candidates.sort(key=lambda x: len(x[1]), reverse=True)
    return candidates[0]


def recompute_consensus_row(row: pd.Series) -> pd.Series:
    raw_texts = {model: str(row.get(col, '') or '').strip() for model, col in TRANSCRIPT_COLS.items()}
    norm_texts = {model: normalize_transcript(txt, remove_fillers=True) for model, txt in raw_texts.items()}
    valid_norm = {m: t for m, t in norm_texts.items() if t.strip()}

    for model, norm in norm_texts.items():
        row[f'{model}_norm'] = norm

    row['available_model_count'] = len(valid_norm)
    row['num_missing_models'] = len(norm_texts) - len(valid_norm)

    if not valid_norm:
        row['agreement_label'] = 'no_transcripts'
        row['majority_text_norm'] = ''
        row['majority_text'] = ''
        row['majority_model'] = ''
        row['majority_strength'] = 0
        row['agreed_models'] = ''
        row['soft_consensus_text_norm'] = ''
        row['soft_consensus_text'] = ''
        row['soft_selected_model'] = ''
        row['soft_agreement_count'] = 0
        row['soft_avg_similarity'] = 0.0
        row['soft_agreed_models'] = ''
        row['avg_pairwise_wer'] = 1.0
        row['avg_pairwise_cer'] = 1.0
        row['avg_pairwise_jaccard'] = 0.0
        row['avg_pairwise_combined_similarity'] = 0.0
        return row

    counter = Counter(valid_norm.values())
    majority_text_norm, majority_strength = counter.most_common(1)[0]
    agreed_models = [m for m, t in valid_norm.items() if t == majority_text_norm]
    majority_model, majority_raw = choose_raw_for_norm(raw_texts, majority_text_norm, agreed_models)

    if majority_strength == len(valid_norm):
        label = 'all_same'
    elif majority_strength >= MIN_CONSENSUS_MODELS:
        label = f'{majority_strength}_agree'
    elif majority_strength == 2:
        label = '2_agree'
    else:
        label = 'all_different'

    row['agreement_label'] = label
    row['majority_text_norm'] = majority_text_norm
    row['majority_text'] = majority_raw
    row['majority_model'] = majority_model
    row['majority_strength'] = int(majority_strength)
    row['agreed_models'] = ','.join(agreed_models)

    # Soft consensus: choose the transcript with strongest average similarity.
    soft_scores = {}
    for m, t in valid_norm.items():
        sims = [combined_similarity(t, ot) for om, ot in valid_norm.items() if om != m]
        soft_scores[m] = float(np.mean(sims)) if sims else 0.0

    soft_selected_model = max(soft_scores, key=soft_scores.get)
    soft_text_norm = valid_norm[soft_selected_model]
    soft_agreed = [
        m for m, t in valid_norm.items()
        if m == soft_selected_model or combined_similarity(soft_text_norm, t) >= SOFT_PAIRWISE_SIM_THRESHOLD
    ]
    row['soft_consensus_text_norm'] = soft_text_norm
    row['soft_consensus_text'] = raw_texts.get(soft_selected_model, '')
    row['soft_selected_model'] = soft_selected_model
    row['soft_agreement_count'] = int(len(soft_agreed))
    row['soft_avg_similarity'] = float(soft_scores[soft_selected_model])
    row['soft_agreed_models'] = ','.join(soft_agreed)

    pairwise_wers = []
    pairwise_cers = []
    pairwise_jaccards = []
    pairwise_sims = []
    for m1, m2 in combinations(valid_norm.keys(), 2):
        t1 = valid_norm[m1]
        t2 = valid_norm[m2]
        w = wer(t1, t2)
        c = cer(t1, t2)
        j = jaccard(t1, t2)
        s = combined_similarity(t1, t2)
        row[f'{m1}_vs_{m2}_wer'] = w
        row[f'{m1}_vs_{m2}_cer'] = c
        row[f'{m1}_vs_{m2}_jaccard'] = j
        row[f'{m1}_vs_{m2}_combined_similarity'] = s
        pairwise_wers.append(w)
        pairwise_cers.append(c)
        pairwise_jaccards.append(j)
        pairwise_sims.append(s)

    row['avg_pairwise_wer'] = float(np.mean(pairwise_wers)) if pairwise_wers else 1.0
    row['avg_pairwise_cer'] = float(np.mean(pairwise_cers)) if pairwise_cers else 1.0
    row['avg_pairwise_jaccard'] = float(np.mean(pairwise_jaccards)) if pairwise_jaccards else 0.0
    row['avg_pairwise_combined_similarity'] = float(np.mean(pairwise_sims)) if pairwise_sims else 0.0
    return row


consensus_work_df = asr_outputs_df.copy()
consensus_df = consensus_work_df.progress_apply(recompute_consensus_row, axis=1)


def choose_final_consensus_text(row: pd.Series) -> Tuple[str, str]:
    if row['available_model_count'] < MIN_CONSENSUS_MODELS:
        return '', 'rejected_insufficient_models'
    if row['majority_strength'] >= MIN_CONSENSUS_MODELS and str(row['majority_text']).strip():
        return row['majority_text'], 'exact_majority'
    if row['soft_agreement_count'] >= MIN_CONSENSUS_MODELS and row['soft_avg_similarity'] >= SOFT_PAIRWISE_SIM_THRESHOLD and str(row['soft_consensus_text']).strip():
        return row['soft_consensus_text'], 'soft_majority'
    return '', 'rejected_no_consensus'


final_texts = consensus_df.apply(choose_final_consensus_text, axis=1)
consensus_df['consensus_text'] = final_texts.apply(lambda x: x[0])
consensus_df['consensus_method'] = final_texts.apply(lambda x: x[1])

consensus_df['consensus_accepted'] = (
    consensus_df['consensus_text'].fillna('').astype(str).str.strip().ne('')
    & (consensus_df['available_model_count'] >= MIN_CONSENSUS_MODELS)
    & (
        ((consensus_df['consensus_method'] == 'exact_majority') & (consensus_df['majority_strength'] >= MIN_CONSENSUS_MODELS))
        | ((consensus_df['consensus_method'] == 'soft_majority') & (consensus_df['soft_agreement_count'] >= MIN_CONSENSUS_MODELS) & (consensus_df['soft_avg_similarity'] >= SOFT_PAIRWISE_SIM_THRESHOLD))
    )
    & (consensus_df['avg_pairwise_wer'] <= MAX_AVG_PAIRWISE_WER)
    & (consensus_df['avg_pairwise_cer'] <= MAX_AVG_PAIRWISE_CER)
    & (consensus_df['avg_pairwise_jaccard'] >= MIN_AVG_PAIRWISE_JACCARD)
)

consensus_df.to_parquet(MANIFESTS_DIR / 'consensus_segments.parquet', index=False)
consensus_df.to_csv(MANIFESTS_DIR / 'consensus_segments.csv', index=False)

print('Consensus accepted:', int(consensus_df['consensus_accepted'].sum()), '/', len(consensus_df))
print('\nConsensus methods:')
display(consensus_df['consensus_method'].value_counts(dropna=False))
print('\nAgreement labels:')
display(consensus_df['agreement_label'].value_counts(dropna=False))

display(consensus_df[[
    'segment_id', 'consensus_accepted', 'consensus_method', 'agreement_label',
    'available_model_count', 'majority_strength', 'soft_agreement_count',
    'avg_pairwise_wer', 'avg_pairwise_cer', 'avg_pairwise_jaccard', 'consensus_text',
]].head(20))

