consensus_df = asr_outputs_df.copy()

raw_arrays = {}
norm_arrays = {}

for model, col in TRANSCRIPT_COLS.items():
    raw_s = consensus_df[col].fillna("").astype(str).str.strip()
    raw_s = raw_s.mask(raw_s.str.lower().isin(["nan", "<na>", "none"]), "")

    norm_s = normalize_series_fast(raw_s, model)

    raw_arrays[model] = raw_s.to_numpy(dtype=object)
    norm_arrays[model] = norm_s.to_numpy(dtype=object)

    consensus_df[f"{model}_norm"] = norm_s

