print("Rows:", n)


# =========================================================
# FAST CONSENSUS LOOP
# =========================================================

def choose_raw_for_norm_fast(
    raw_texts: Dict[str, str],
    norm_texts: Dict[str, str],
    norm_target: str,
    preferred_models: Optional[List[str]] = None,
) -> Tuple[str, str]:
    preferred_models = preferred_models or list(raw_texts.keys())

    candidates = []

    for model in preferred_models:
        raw = str(raw_texts.get(model, "") or "").strip()
        norm = str(norm_texts.get(model, "") or "").strip()

        if raw and norm == norm_target:
            candidates.append((model, raw))

    if not candidates:
        for model, raw in raw_texts.items():
            raw = str(raw or "").strip()
            if raw:
                candidates.append((model, raw))

    if not candidates:
        return "", ""

    candidates.sort(key=lambda x: len(x[1]), reverse=True)
    return candidates[0]


base_output_cols = [
    "available_model_count",
    "num_missing_models",
    "agreement_label",
    "majority_text_norm",
    "majority_text",
    "majority_model",
    "majority_strength",
    "agreed_models",
    "soft_consensus_text_norm",
    "soft_consensus_text",
    "soft_selected_model",
    "soft_agreement_count",
    "soft_avg_similarity",
    "soft_agreed_models",
    "avg_pairwise_wer",
    "avg_pairwise_cer",
    "avg_pairwise_jaccard",
    "avg_pairwise_combined_similarity",
]

out = {col: [] for col in base_output_cols}

for m1, m2 in PAIR_KEYS:
    out[f"{m1}_vs_{m2}_wer"] = []
    out[f"{m1}_vs_{m2}_cer"] = []
    out[f"{m1}_vs_{m2}_jaccard"] = []
    out[f"{m1}_vs_{m2}_combined_similarity"] = []


for i in tqdm(range(n), desc="Fast consensus", mininterval=1):
    raw_texts = {m: raw_arrays[m][i] for m in MODELS}
    norm_texts = {m: norm_arrays[m][i] for m in MODELS}

    valid_models = [m for m in MODELS if str(norm_texts[m]).strip()]
    valid_set = set(valid_models)
    valid_norm = {m: norm_texts[m] for m in valid_models}

    available_count = len(valid_models)
    missing_count = len(MODELS) - available_count

    out["available_model_count"].append(int(available_count))
    out["num_missing_models"].append(int(missing_count))

    pairwise_wers = []
    pairwise_cers = []
    pairwise_jaccards = []
    pairwise_sims = []

    for m1, m2 in PAIR_KEYS:
        if m1 in valid_set and m2 in valid_set:
            t1 = norm_texts[m1]
            t2 = norm_texts[m2]

            w, c, j, s = pair_metrics_cached(t1, t2)

            out[f"{m1}_vs_{m2}_wer"].append(w)
            out[f"{m1}_vs_{m2}_cer"].append(c)
            out[f"{m1}_vs_{m2}_jaccard"].append(j)
            out[f"{m1}_vs_{m2}_combined_similarity"].append(s)

            pairwise_wers.append(w)
            pairwise_cers.append(c)
            pairwise_jaccards.append(j)
            pairwise_sims.append(s)
        else:
            out[f"{m1}_vs_{m2}_wer"].append(np.nan)
            out[f"{m1}_vs_{m2}_cer"].append(np.nan)
            out[f"{m1}_vs_{m2}_jaccard"].append(np.nan)
            out[f"{m1}_vs_{m2}_combined_similarity"].append(np.nan)

    if not valid_norm:
        out["agreement_label"].append("no_transcripts")
        out["majority_text_norm"].append("")
        out["majority_text"].append("")
        out["majority_model"].append("")
        out["majority_strength"].append(0)
        out["agreed_models"].append("")
        out["soft_consensus_text_norm"].append("")
        out["soft_consensus_text"].append("")
        out["soft_selected_model"].append("")
        out["soft_agreement_count"].append(0)
        out["soft_avg_similarity"].append(0.0)
        out["soft_agreed_models"].append("")
        out["avg_pairwise_wer"].append(1.0)
        out["avg_pairwise_cer"].append(1.0)
        out["avg_pairwise_jaccard"].append(0.0)
        out["avg_pairwise_combined_similarity"].append(0.0)
        continue

    counter = Counter(valid_norm.values())
    majority_text_norm, majority_strength = counter.most_common(1)[0]

    agreed_models = [
        m for m, t in valid_norm.items()
        if t == majority_text_norm
    ]

    majority_model, majority_raw = choose_raw_for_norm_fast(
        raw_texts=raw_texts,
        norm_texts=norm_texts,
        norm_target=majority_text_norm,
        preferred_models=agreed_models,
    )

    if majority_strength == available_count:
        agreement_label = "all_same"
    elif majority_strength >= MIN_CONSENSUS_MODELS:
        agreement_label = f"{majority_strength}_agree"
    elif majority_strength == 2:
        agreement_label = "2_agree"
    else:
        agreement_label = "all_different"

    out["agreement_label"].append(agreement_label)
    out["majority_text_norm"].append(majority_text_norm)
    out["majority_text"].append(majority_raw)
    out["majority_model"].append(majority_model)
    out["majority_strength"].append(int(majority_strength))
    out["agreed_models"].append(",".join(agreed_models))

    # Soft consensus
    soft_scores = {}

    for m in valid_models:
        t = norm_texts[m]
        sims = [
            combined_similarity_fast(t, norm_texts[om])
            for om in valid_models
            if om != m
        ]
        soft_scores[m] = float(np.mean(sims)) if sims else 0.0

    soft_selected_model = max(soft_scores, key=soft_scores.get)
    soft_text_norm = norm_texts[soft_selected_model]

    soft_agreed = [
        m for m in valid_models
        if (
            m == soft_selected_model
            or combined_similarity_fast(soft_text_norm, norm_texts[m]) >= SOFT_PAIRWISE_SIM_THRESHOLD
        )
    ]

    out["soft_consensus_text_norm"].append(soft_text_norm)
    out["soft_consensus_text"].append(raw_texts.get(soft_selected_model, ""))
    out["soft_selected_model"].append(soft_selected_model)
    out["soft_agreement_count"].append(int(len(soft_agreed)))
    out["soft_avg_similarity"].append(float(soft_scores[soft_selected_model]))
    out["soft_agreed_models"].append(",".join(soft_agreed))

    out["avg_pairwise_wer"].append(float(np.mean(pairwise_wers)) if pairwise_wers else 1.0)
    out["avg_pairwise_cer"].append(float(np.mean(pairwise_cers)) if pairwise_cers else 1.0)
    out["avg_pairwise_jaccard"].append(float(np.mean(pairwise_jaccards)) if pairwise_jaccards else 0.0)
    out["avg_pairwise_combined_similarity"].append(float(np.mean(pairwise_sims)) if pairwise_sims else 0.0)


for col, values in out.items():
    consensus_df[col] = values


# =========================================================
# FINAL CONSENSUS SELECTION
# =========================================================

available = consensus_df["available_model_count"].to_numpy()
majority_strength = consensus_df["majority_strength"].to_numpy()
soft_count = consensus_df["soft_agreement_count"].to_numpy()
soft_avg = consensus_df["soft_avg_similarity"].to_numpy()

majority_text = consensus_df["majority_text"].fillna("").astype(str).str.strip().to_numpy()
soft_text = consensus_df["soft_consensus_text"].fillna("").astype(str).str.strip().to_numpy()

consensus_text = np.full(n, "", dtype=object)
consensus_method = np.full(n, "rejected_no_consensus", dtype=object)

insufficient_mask = available < MIN_CONSENSUS_MODELS
consensus_method[insufficient_mask] = "rejected_insufficient_models"

exact_mask = (
    ~insufficient_mask
    & (majority_strength >= MIN_CONSENSUS_MODELS)
    & (majority_text != "")
)

consensus_text[exact_mask] = majority_text[exact_mask]
consensus_method[exact_mask] = "exact_majority"

soft_mask = (
    ~insufficient_mask
    & ~exact_mask
    & (soft_count >= MIN_CONSENSUS_MODELS)
    & (soft_avg >= SOFT_PAIRWISE_SIM_THRESHOLD)
    & (soft_text != "")
)

consensus_text[soft_mask] = soft_text[soft_mask]
consensus_method[soft_mask] = "soft_majority"

consensus_df["consensus_text"] = consensus_text
consensus_df["consensus_method"] = consensus_method

consensus_df["consensus_accepted"] = (
    consensus_df["consensus_text"].fillna("").astype(str).str.strip().ne("")
    & (consensus_df["available_model_count"] >= MIN_CONSENSUS_MODELS)
    & (
        (
            (consensus_df["consensus_method"] == "exact_majority")
            & (consensus_df["majority_strength"] >= MIN_CONSENSUS_MODELS)
        )
        | (
            (consensus_df["consensus_method"] == "soft_majority")
            & (consensus_df["soft_agreement_count"] >= MIN_CONSENSUS_MODELS)
            & (consensus_df["soft_avg_similarity"] >= SOFT_PAIRWISE_SIM_THRESHOLD)
        )
    )
    & (consensus_df["avg_pairwise_wer"].fillna(1.0) <= MAX_AVG_PAIRWISE_WER)
    & (consensus_df["avg_pairwise_cer"].fillna(1.0) <= MAX_AVG_PAIRWISE_CER)
    & (consensus_df["avg_pairwise_jaccard"].fillna(0.0) >= MIN_AVG_PAIRWISE_JACCARD)
)


# =========================================================
# SAVE
# =========================================================

consensus_parquet_path = MANIFESTS_DIR / "consensus_segments.parquet"
consensus_csv_path = MANIFESTS_DIR / "consensus_segments.csv"

consensus_df.to_parquet(consensus_parquet_path, index=False)

if WRITE_CONSENSUS_CSV:
    consensus_df.to_csv(consensus_csv_path, index=False)

elapsed_min = (time.time() - t0) / 60

print("Saved parquet:", consensus_parquet_path)

if WRITE_CONSENSUS_CSV:
    print("Saved csv:", consensus_csv_path)
else:
    print("CSV skipped for speed. Set WRITE_CONSENSUS_CSV=True if needed.")

print(f"Elapsed minutes: {elapsed_min:.2f}")
print("Consensus accepted:", int(consensus_df["consensus_accepted"].sum()), "/", len(consensus_df))

print("\nConsensus methods:")
display(consensus_df["consensus_method"].value_counts(dropna=False))

print("\nAgreement labels:")
display(consensus_df["agreement_label"].value_counts(dropna=False))

print("\nNormalization cache:")
print(normalize_transcript_cached.cache_info())

print("\nPair metric cache:")
print(pair_metrics_cached.cache_info())

