import numpy as np
import pandas as pd
from pathlib import Path

SEG_EMBED_MIN_USABLE_SEC = 0.50
SEG_EMBED_MAX_CLIP_RATIO = 0.05
SEG_EMBED_REQUIRE_AUDIO_TRAINABLE = True
SEG_EMBED_REQUIRE_ENGLISH = True

seg_embed_df = source_df.copy()

seg_embed_df["call_id"] = seg_embed_df["call_id"].astype(str)
seg_embed_df["channel"] = seg_embed_df["channel"].astype(str)
seg_embed_df["segment_id"] = seg_embed_df["segment_id"].astype(str)
seg_embed_df["audio_filepath"] = seg_embed_df["audio_filepath"].astype(str)

seg_embed_df["usable_speech_sec"] = pd.to_numeric(
    seg_embed_df["usable_speech_sec"],
    errors="coerce",
).fillna(0.0)

seg_embed_df["duration"] = pd.to_numeric(
    seg_embed_df["duration"],
    errors="coerce",
).fillna(seg_embed_df["usable_speech_sec"])

if "segment_clip_ratio" not in seg_embed_df.columns:
    seg_embed_df["segment_clip_ratio"] = 0.0

seg_embed_df["segment_clip_ratio"] = pd.to_numeric(
    seg_embed_df["segment_clip_ratio"],
    errors="coerce",
).fillna(0.0)

if "segment_speech_ratio" not in seg_embed_df.columns:
    seg_embed_df["segment_speech_ratio"] = 1.0

seg_embed_df["segment_speech_ratio"] = pd.to_numeric(
    seg_embed_df["segment_speech_ratio"],
    errors="coerce",
).fillna(1.0)

if "is_audio_trainable" not in seg_embed_df.columns:
    seg_embed_df["is_audio_trainable"] = True

if "is_english" not in seg_embed_df.columns:
    seg_embed_df["is_english"] = True

mask = (
    (seg_embed_df["usable_speech_sec"] >= SEG_EMBED_MIN_USABLE_SEC)
    & (seg_embed_df["segment_clip_ratio"] < SEG_EMBED_MAX_CLIP_RATIO)
)

if SEG_EMBED_REQUIRE_AUDIO_TRAINABLE:
    mask &= seg_embed_df["is_audio_trainable"].fillna(True).astype(bool)

if SEG_EMBED_REQUIRE_ENGLISH:
    mask &= seg_embed_df["is_english"].fillna(True).astype(bool)

seg_embed_df = seg_embed_df[mask].copy().reset_index(drop=True)

print("Total consensus rows:", len(source_df))
