FINAL_OUT_DIR = OUT_DIR / "final_exports"

for d in [OUT_DIR, CLUSTER_OUT_DIR, LABEL_OUT_DIR, SPLIT_OUT_DIR, FINAL_OUT_DIR]:
    d.mkdir(parents=True, exist_ok=True)

# Speaker clustering config from your final notebook approach.
MIN_SEGMENT_SPEECH_SEC = 2.0
MIN_SEGMENT_SPEECH_RATIO = 0.90
MAX_SEGMENT_CLIP_RATIO = 0.005

MAX_SEGMENTS_PER_CALL_SIDE = 30
MIN_SEGMENTS_PER_CALL_SIDE = 3

# Final threshold from your notebook's final successful version.
SPEAKER_SIM_THRESHOLD = 0.80

# Train split config.
TRAIN_RATIO = 0.80
VALID_RATIO = 0.10
TEST_RATIO = 0.10

# CSV writing is slow for large segment-level data.
WRITE_FINAL_CSV = False

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
device_type = "cuda" if torch.cuda.is_available() else "cpu"

print("Rows in consensus_df:", len(consensus_df))
print("Output:", OUT_DIR)
print("Device:", device)

# ============================================================
# PREPARE SOURCE DF FROM CONSENSUS_DF
# ============================================================

source_df = consensus_df.copy()

source_df["segment_id"] = source_df["segment_id"].astype(str)

required_base = ["segment_id", "call_id", "audio_filepath"]
missing = [c for c in required_base if c not in source_df.columns]
if missing:
    raise ValueError(f"Missing required columns in consensus_df: {missing}")

source_df["call_id"] = source_df["call_id"].astype(str)
source_df["audio_filepath"] = source_df["audio_filepath"].astype(str)

# Normalize channel column.
if "channel" in source_df.columns:
    source_df["channel"] = source_df["channel"].astype(str)
elif "channel_idx" in source_df.columns:
    source_df["channel"] = source_df["channel_idx"].astype(str)
else:
    raise ValueError("Need either 'channel' or 'channel_idx' in consensus_df")

# Ensure duration fields exist.
if "duration" not in source_df.columns:
    if {"start_sample", "end_sample"}.issubset(source_df.columns):
        source_df["duration"] = (
            pd.to_numeric(source_df["end_sample"], errors="coerce")
            - pd.to_numeric(source_df["start_sample"], errors="coerce")
        ) / TARGET_SR
    else:
        source_df["duration"] = np.nan

if "usable_speech_sec" not in source_df.columns:
    source_df["usable_speech_sec"] = source_df["duration"]

# Timing fields for call-level transcript ordering.
if "start_sec" not in source_df.columns:
    if "start_sample" in source_df.columns:
        source_df["start_sec"] = pd.to_numeric(source_df["start_sample"], errors="coerce") / TARGET_SR
    else:
        source_df["start_sec"] = np.nan

if "end_sec" not in source_df.columns:
    if "end_sample" in source_df.columns:
        source_df["end_sec"] = pd.to_numeric(source_df["end_sample"], errors="coerce") / TARGET_SR
    else:
        source_df["end_sec"] = source_df["start_sec"] + pd.to_numeric(source_df["duration"], errors="coerce")

# Speaker clustering quality columns.
if "segment_speech_ratio" not in source_df.columns:
    source_df["segment_speech_ratio"] = 1.0

if "segment_clip_ratio" not in source_df.columns:
    source_df["segment_clip_ratio"] = 0.0

# Final transcript for training.
source_df["consensus_text"] = (
    source_df.get("consensus_text", "")
    .fillna("")
    .astype(str)
    .str.strip()
)

source_df["consensus_accepted"] = (
    source_df.get("consensus_accepted", False)
    .fillna(False)
    .astype(bool)
)

source_df["final_candidate_transcript"] = np.where(
    source_df["consensus_accepted"],
    source_df["consensus_text"],
    "",
)

source_df["has_final_candidate_transcript"] = (
    source_df["final_candidate_transcript"]
    .fillna("")
    .astype(str)
    .str.strip()
    .ne("")
)

source_df["is_high_confidence_pseudo_label"] = False

if "agreement_label" in source_df.columns:
    source_df["is_high_confidence_pseudo_label"] |= source_df["agreement_label"].isin(
        ["all_same", "3_agree"]
    )

if "majority_strength" in source_df.columns:
    source_df["is_high_confidence_pseudo_label"] |= (
        pd.to_numeric(source_df["majority_strength"], errors="coerce").fillna(0) >= 3
    )

if "soft_agreement_count" in source_df.columns:
    source_df["is_high_confidence_pseudo_label"] |= (
        pd.to_numeric(source_df["soft_agreement_count"], errors="coerce").fillna(0) >= 3
    )

# Keep only existing audio.
source_df = source_df[source_df["audio_filepath"].apply(lambda p: Path(p).exists())].copy()
source_df = source_df.drop_duplicates("segment_id").reset_index(drop=True)

print("Source rows:", len(source_df))
print("Unique calls:", source_df["call_id"].nunique())
print("Unique call-sides:", source_df[["call_id", "channel"]].drop_duplicates().shape[0])
print("Accepted consensus rows:", int(source_df["consensus_accepted"].sum()))
print("High-confidence rows:", int(source_df["is_high_confidence_pseudo_label"].sum()))

# ============================================================
# SELECT CLEAN SEGMENTS FOR SPEAKER CLUSTERING
# ============================================================

embed_df = source_df[
    (pd.to_numeric(source_df["usable_speech_sec"], errors="coerce").fillna(0) >= MIN_SEGMENT_SPEECH_SEC)
    & (pd.to_numeric(source_df["segment_speech_ratio"], errors="coerce").fillna(1.0) >= MIN_SEGMENT_SPEECH_RATIO)
    & (pd.to_numeric(source_df["segment_clip_ratio"], errors="coerce").fillna(0.0) < MAX_SEGMENT_CLIP_RATIO)
].copy()

if "is_english" in embed_df.columns:
    embed_df = embed_df[embed_df["is_english"].fillna(False).astype(bool)].copy()

if "segment_rms" in embed_df.columns:
    rms = pd.to_numeric(embed_df["segment_rms"], errors="coerce")
    lo = rms.quantile(0.02)
    hi = rms.quantile(0.995)
    embed_df = embed_df[rms.between(lo, hi)].copy()

# Prefer longer clean segments, capped per call-side.
embed_df = (
    embed_df
    .sort_values(
        ["call_id", "channel", "usable_speech_sec", "segment_speech_ratio"],
        ascending=[True, True, False, False],
    )
    .groupby(["call_id", "channel"], group_keys=False)
    .head(MAX_SEGMENTS_PER_CALL_SIDE)
    .reset_index(drop=True)
)

side_counts = (
    embed_df
    .groupby(["call_id", "channel"])
    .size()
    .reset_index(name="selected_embedding_segments")
)

valid_sides = side_counts[
    side_counts["selected_embedding_segments"] >= MIN_SEGMENTS_PER_CALL_SIDE
][["call_id", "channel"]]

embed_df = embed_df.merge(valid_sides, on=["call_id", "channel"], how="inner")

print("Embedding rows:", len(embed_df))
print("Embedding call-sides:", embed_df[["call_id", "channel"]].drop_duplicates().shape[0])
display(embed_df[["segment_id", "call_id", "channel", "duration", "usable_speech_sec", "audio_filepath"]].head())

