import numpy as np
import pandas as pd
from pathlib import Path

# Speed/quality tradeoff:
# 5 = faster
# 8 = good default
# 12 = stronger but slower
MAX_SEGMENTS_PER_CALL_SIDE_FAST = 8
MIN_SEGMENTS_PER_CALL_SIDE_FAST = 2

MIN_SEGMENT_SPEECH_SEC_FAST = 1.5
MIN_SEGMENT_SPEECH_RATIO_FAST = 0.85
MAX_SEGMENT_CLIP_RATIO_FAST = 0.01

embed_source_df = source_df.copy()

embed_source_df["usable_speech_sec"] = pd.to_numeric(
    embed_source_df["usable_speech_sec"],
    errors="coerce",
).fillna(0.0)

embed_source_df["duration"] = pd.to_numeric(
    embed_source_df["duration"],
    errors="coerce",
).fillna(embed_source_df["usable_speech_sec"])

embed_source_df["segment_speech_ratio"] = pd.to_numeric(
    embed_source_df.get("segment_speech_ratio", 1.0),
    errors="coerce",
).fillna(1.0)

embed_source_df["segment_clip_ratio"] = pd.to_numeric(
    embed_source_df.get("segment_clip_ratio", 0.0),
    errors="coerce",
).fillna(0.0)

if "is_english" not in embed_source_df.columns:
    embed_source_df["is_english"] = True

if "is_audio_trainable" not in embed_source_df.columns:
    embed_source_df["is_audio_trainable"] = True

# Base quality filter
embed_df_fast = embed_source_df[
    (embed_source_df["is_audio_trainable"].fillna(True).astype(bool))
    & (embed_source_df["is_english"].fillna(True).astype(bool))
    & (embed_source_df["usable_speech_sec"] >= MIN_SEGMENT_SPEECH_SEC_FAST)
    & (embed_source_df["segment_speech_ratio"] >= MIN_SEGMENT_SPEECH_RATIO_FAST)
    & (embed_source_df["segment_clip_ratio"] < MAX_SEGMENT_CLIP_RATIO_FAST)
].copy()

# Optional RMS filtering if available
if "segment_rms" in embed_df_fast.columns:
    rms = pd.to_numeric(embed_df_fast["segment_rms"], errors="coerce")
    lo = rms.quantile(0.01)
    hi = rms.quantile(0.995)
    embed_df_fast = embed_df_fast[rms.between(lo, hi)].copy()

# Prefer accepted/high-confidence, clean, longer clips
sort_cols = ["call_id", "channel"]
ascending = [True, True]

if "is_high_confidence_pseudo_label" in embed_df_fast.columns:
    sort_cols.append("is_high_confidence_pseudo_label")
    ascending.append(False)

if "consensus_accepted" in embed_df_fast.columns:
    sort_cols.append("consensus_accepted")
    ascending.append(False)

sort_cols += ["segment_speech_ratio", "usable_speech_sec"]
ascending += [False, False]

embed_df_fast = (
    embed_df_fast
    .sort_values(sort_cols, ascending=ascending)
    .groupby(["call_id", "channel"], group_keys=False)
    .head(MAX_SEGMENTS_PER_CALL_SIDE_FAST)
    .reset_index(drop=True)
)

# Keep call-sides with enough segments
side_counts = (
    embed_df_fast
    .groupby(["call_id", "channel"])
    .size()
    .reset_index(name="selected_embedding_segments")
)

valid_sides = side_counts[
    side_counts["selected_embedding_segments"] >= MIN_SEGMENTS_PER_CALL_SIDE_FAST
][["call_id", "channel"]]

embed_df_fast = embed_df_fast.merge(
    valid_sides,
    on=["call_id", "channel"],
    how="inner",
).reset_index(drop=True)

print("Old embed_df rows:", len(embed_df) if "embed_df" in globals() else "not loaded")
print("Fast embed_df rows:", len(embed_df_fast))
print("Fast call-sides:", embed_df_fast[["call_id", "channel"]].drop_duplicates().shape[0])

display(
    side_counts["selected_embedding_segments"]
    .describe()
)

display(
    embed_df_fast[
        ["segment_id", "call_id", "channel", "duration", "usable_speech_sec", "audio_filepath"]
    ].head()
)

