import gc
import time
import numpy as np
import pandas as pd
import torch
import torchaudio
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
from tqdm.auto import tqdm

# ----------------------------
# Speed config
# ----------------------------

EMBED_BATCH_SIZE = 128          # try 64 if OOM, try 192/256 if GPU memory is fine
EMBED_LOAD_WORKERS = 8          # CPU workers for audio loading
EMBED_MAX_SEC = 3.0             # speaker embedding does not need full long segment
EMBED_MIN_SEC = 1.0
SAVE_EVERY_BATCHES = 50

TARGET_SR = 16000

EMB_FAST_PATH = CLUSTER_OUT_DIR / f"segment_embeddings_redimnet_fast_{EMBED_MAX_SEC}s_max{MAX_SEGMENTS_PER_CALL_SIDE_FAST}.npy"
META_FAST_PATH = CLUSTER_OUT_DIR / f"segment_embedding_metadata_fast_{EMBED_MAX_SEC}s_max{MAX_SEGMENTS_PER_CALL_SIDE_FAST}.csv"
ERR_FAST_PATH = CLUSTER_OUT_DIR / f"segment_embedding_errors_fast_{EMBED_MAX_SEC}s_max{MAX_SEGMENTS_PER_CALL_SIDE_FAST}.csv"

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
device_type = "cuda" if torch.cuda.is_available() else "cpu"

torch.backends.cuda.matmul.allow_tf32 = True
torch.backends.cudnn.allow_tf32 = True
torch.backends.cudnn.benchmark = True


def clear_cuda():
    gc.collect()
    if torch.cuda.is_available():
        torch.cuda.empty_cache()


def l2_normalize_matrix(X):
    return X / (np.linalg.norm(X, axis=1, keepdims=True) + 1e-12)


def l2_normalize_vector(x):
    return x / (np.linalg.norm(x) + 1e-12)


clear_cuda()

# Load ReDimNet
model = torch.hub.load(
    "IDRnD/ReDimNet",
    "ReDimNet",
    model_name="M",
    train_type="ft_mix",
    dataset="vb2+vox2+cnc",
    trust_repo=True,
)

model = model.to(device)
model.eval()

print("ReDimNet loaded")
print("device:", device)
print("batch size:", EMBED_BATCH_SIZE)
print("max sec:", EMBED_MAX_SEC)
print("fast embedding path:", EMB_FAST_PATH)


def load_audio_for_embedding(item):
    """
    item is a dict-like row.
    Returns:
        ok, row_metadata, waveform_1d_or_error
    """
    try:
        path = str(item["audio_filepath"])

        wav, sr = torchaudio.load(path)

        if wav.ndim == 2 and wav.shape[0] > 1:
            wav = wav.mean(dim=0, keepdim=True)

        if sr != TARGET_SR:
            wav = torchaudio.functional.resample(wav, sr, TARGET_SR)

        wav = wav.squeeze(0).float()

        wav = torch.nan_to_num(wav, nan=0.0, posinf=0.0, neginf=0.0)

        max_len = int(EMBED_MAX_SEC * TARGET_SR)
        min_len = int(EMBED_MIN_SEC * TARGET_SR)

        n = wav.numel()

        if n == 0:
            wav = torch.zeros(min_len, dtype=torch.float32)
            n = min_len

        # Center crop long clips
        if n > max_len:
            start = max(0, (n - max_len) // 2)
            wav = wav[start:start + max_len]
            n = wav.numel()

        # Pad very short clips
        if n < min_len:
            wav = torch.nn.functional.pad(wav, (0, min_len - n))

        meta = {
            "segment_id": str(item["segment_id"]),
            "audio_filepath": path,
            "call_id": str(item["call_id"]),
            "channel": str(item["channel"]),
            "start_sec": item.get("start_sec", np.nan),
            "end_sec": item.get("end_sec", np.nan),
            "duration": item.get("duration", np.nan),
            "usable_speech_sec": item.get("usable_speech_sec", np.nan),
            "segment_speech_ratio": item.get("segment_speech_ratio", np.nan),
            "segment_rms": item.get("segment_rms", np.nan),
            "segment_clip_ratio": item.get("segment_clip_ratio", np.nan),
            "embed_audio_samples": int(wav.numel()),
        }

        return True, meta, wav

    except Exception as e:
        meta = {
            "segment_id": str(item.get("segment_id", "")),
            "audio_filepath": str(item.get("audio_filepath", "")),
            "call_id": str(item.get("call_id", "")),
            "channel": str(item.get("channel", "")),
            "embedding_error": repr(e),
        }

        return False, meta, None


def make_padded_batch(wavs):
    lengths = [w.numel() for w in wavs]
    max_len = max(lengths)

    batch = torch.zeros((len(wavs), max_len), dtype=torch.float32)

    for i, w in enumerate(wavs):
        batch[i, :w.numel()] = w

    return batch


# ----------------------------
# Resume support
# ----------------------------

if EMB_FAST_PATH.exists() and META_FAST_PATH.exists():
    existing_emb = np.load(EMB_FAST_PATH).astype("float32")
    existing_meta = pd.read_csv(META_FAST_PATH)

    embeddings = [existing_emb[i] for i in range(existing_emb.shape[0])]
    meta_rows = existing_meta.to_dict("records")
    done_ids = set(existing_meta["segment_id"].astype(str))

    if ERR_FAST_PATH.exists():
        error_rows = pd.read_csv(ERR_FAST_PATH).to_dict("records")
    else:
        error_rows = []

    print("Resuming fast embeddings. Done:", len(done_ids))

else:
    embeddings = []
    meta_rows = []
    error_rows = []
    done_ids = set()

    print("Starting fresh fast embedding extraction")


pending_df = embed_df_fast[
    ~embed_df_fast["segment_id"].astype(str).isin(done_ids)
].copy().reset_index(drop=True)

print("Pending rows:", len(pending_df))

records = pending_df.to_dict("records")

loader_pool = ThreadPoolExecutor(max_workers=EMBED_LOAD_WORKERS)

start_time = time.time()
num_batches = int(np.ceil(len(records) / EMBED_BATCH_SIZE))

for batch_idx in tqdm(range(num_batches), desc="Fast batched ReDimNet embeddings"):
    batch_records = records[
        batch_idx * EMBED_BATCH_SIZE : (batch_idx + 1) * EMBED_BATCH_SIZE
    ]

    loaded = list(loader_pool.map(load_audio_for_embedding, batch_records))

    ok_items = [x for x in loaded if x[0]]
    bad_items = [x for x in loaded if not x[0]]

    for _, err_meta, _ in bad_items:
        error_rows.append(err_meta)

    if len(ok_items) == 0:
        continue

    batch_meta = [x[1] for x in ok_items]
    wavs = [x[2] for x in ok_items]

    try:
        batch_audio = make_padded_batch(wavs).to(device, non_blocking=True)

        precision = torch.float16 if torch.cuda.is_available() else torch.float32

        with torch.inference_mode():
            with torch.autocast(device_type=device_type, dtype=precision, enabled=torch.cuda.is_available()):
                emb = model(batch_audio)

        emb = emb.detach().cpu().float().numpy()

        if emb.ndim == 3 and emb.shape[1] == 1:
            emb = emb[:, 0, :]
        elif emb.ndim > 2:
            emb = emb.reshape(emb.shape[0], -1)

        emb = l2_normalize_matrix(emb.astype("float32"))

        embeddings.extend([emb[i] for i in range(emb.shape[0])])
        meta_rows.extend(batch_meta)

    except torch.cuda.OutOfMemoryError as e:
        torch.cuda.empty_cache()

        # Fallback: process this batch in smaller chunks
        half = max(1, len(wavs) // 2)

        for sub_start in range(0, len(wavs), half):
            sub_wavs = wavs[sub_start:sub_start + half]
            sub_meta = batch_meta[sub_start:sub_start + half]

            try:
                sub_audio = make_padded_batch(sub_wavs).to(device, non_blocking=True)

                with torch.inference_mode():
                    with torch.autocast(device_type=device_type, dtype=torch.float16, enabled=torch.cuda.is_available()):
                        sub_emb = model(sub_audio)

                sub_emb = sub_emb.detach().cpu().float().numpy()

                if sub_emb.ndim == 3 and sub_emb.shape[1] == 1:
                    sub_emb = sub_emb[:, 0, :]
                elif sub_emb.ndim > 2:
                    sub_emb = sub_emb.reshape(sub_emb.shape[0], -1)

                sub_emb = l2_normalize_matrix(sub_emb.astype("float32"))

                embeddings.extend([sub_emb[i] for i in range(sub_emb.shape[0])])
                meta_rows.extend(sub_meta)

            except Exception as sub_e:
                for m in sub_meta:
                    mm = dict(m)
                    mm["embedding_error"] = repr(sub_e)
                    error_rows.append(mm)

    except Exception as e:
        for m in batch_meta:
            mm = dict(m)
            mm["embedding_error"] = repr(e)
            error_rows.append(mm)

    # checkpoint
    if (batch_idx + 1) % SAVE_EVERY_BATCHES == 0:
        if len(embeddings) > 0:
            np.save(EMB_FAST_PATH, np.vstack(embeddings).astype("float32"))
            pd.DataFrame(meta_rows).to_csv(META_FAST_PATH, index=False)

        pd.DataFrame(error_rows).to_csv(ERR_FAST_PATH, index=False)

        elapsed = time.time() - start_time
        done = len(meta_rows)
        rate = done / max(elapsed, 1e-9)

        print(
            f"checkpoint batch={batch_idx + 1}/{num_batches}, "
            f"done={done}, errors={len(error_rows)}, rate={rate:.2f} emb/sec"
        )

# Final save
if len(embeddings) == 0:
    raise RuntimeError("No embeddings extracted.")

np.save(EMB_FAST_PATH, np.vstack(embeddings).astype("float32"))
pd.DataFrame(meta_rows).to_csv(META_FAST_PATH, index=False)
pd.DataFrame(error_rows).to_csv(ERR_FAST_PATH, index=False)

loader_pool.shutdown(wait=False)

elapsed = time.time() - start_time

print("Saved embeddings:", EMB_FAST_PATH)
print("Saved metadata:", META_FAST_PATH)
print("Saved errors:", ERR_FAST_PATH)
print("Embedding shape:", np.vstack(embeddings).shape)
print("Metadata rows:", len(meta_rows))
print("Errors:", len(error_rows))
print("Elapsed min:", elapsed / 60)
print("Rate emb/sec:", len(meta_rows) / max(elapsed, 1e-9))

# Make later clustering cells use the fast paths
EMB_PATH = EMB_FAST_PATH
META_PATH = META_FAST_PATH
ERR_PATH = ERR_FAST_PATH

del model
clear_cuda()

EMB_PATH = EMB_FAST_PATH
