def l2_normalize_matrix(X):
    return X / (np.linalg.norm(X, axis=1, keepdims=True) + 1e-12)


def robust_centroid(E):
    """
    Final notebook approach:
    1. L2 normalize segment embeddings
    2. Compute initial centroid
    3. Drop worst 20 percent by similarity to centroid
    4. Recompute centroid
    """
    E = l2_normalize_matrix(E.astype("float32"))

    c1 = E.mean(axis=0)
    c1 = l2_normalize_vector(c1)

    sims1 = E @ c1

    if len(E) >= 5:
        cutoff = np.quantile(sims1, 0.20)
        E2 = E[sims1 >= cutoff]
    else:
        E2 = E

    c2 = E2.mean(axis=0)
    c2 = l2_normalize_vector(c2)

    sims2 = E @ c2

    return {
        "centroid": c2.astype("float32"),
        "n_segment_embeddings": int(len(E)),
        "centroid_mean_sim": float(np.mean(sims2)),
        "centroid_p10_sim": float(np.quantile(sims2, 0.10)),
        "centroid_min_sim": float(np.min(sims2)),
    }


side_rows = []
side_centroids = []

for (call_id, channel), g in tqdm(meta_df.groupby(["call_id", "channel"]), desc="Building call-side centroids"):
    idx = g.index.to_numpy()
    E = embeddings[idx]

    if len(E) < MIN_SEGMENTS_PER_CALL_SIDE:
        continue

    result = robust_centroid(E)
    side_centroids.append(result["centroid"])

    side_rows.append({
        "call_id": call_id,
        "channel": channel,
        "n_segment_embeddings": result["n_segment_embeddings"],
        "centroid_mean_sim": result["centroid_mean_sim"],
        "centroid_p10_sim": result["centroid_p10_sim"],
        "centroid_min_sim": result["centroid_min_sim"],
    })

side_df = pd.DataFrame(side_rows)
side_centroids = np.vstack(side_centroids).astype("float32")

side_stats = (
    source_df
    .groupby(["call_id", "channel"])
    .agg(
        total_segments=("segment_id", "count"),
        total_usable_speech_sec=("usable_speech_sec", "sum"),
        total_duration_sec=("duration", "sum"),
    )
    .reset_index()
)

side_df = side_df.merge(side_stats, on=["call_id", "channel"], how="left")

