def same_call_opposite_channel_sims(side_df, C):
    sims = []

    for call_id, g in side_df.groupby("call_id"):
        if g["channel"].nunique() < 2:
            continue

        idxs = g.index.to_list()

        for i in range(len(idxs)):
            for j in range(i + 1, len(idxs)):
                a = idxs[i]
                b = idxs[j]

                if side_df.loc[a, "channel"] != side_df.loc[b, "channel"]:
                    sims.append(float(C[a] @ C[b]))

    return np.array(sims, dtype="float32")


neg_sims = same_call_opposite_channel_sims(side_df, side_centroids)

print("Same-call opposite-channel similarities:")
