segments_with_speakers["speaker_cluster_id"] = segments_with_speakers["speaker_cluster_id"].fillna("spk_unknown")

segments_with_speakers["is_unknown_speaker_cluster"] = (
    segments_with_speakers["speaker_cluster_id"]
    .astype(str)
    .str.contains("unknown", case=False, na=False)
)

# Give every unknown call-side its own fallback speaker cluster.
unknown_side_map = (
    segments_with_speakers[
        segments_with_speakers["is_unknown_speaker_cluster"]
    ][["call_id", "channel"]]
    .drop_duplicates()
    .sort_values(["call_id", "channel"])
    .reset_index(drop=True)
)

if len(unknown_side_map) > 0:
    max_cluster = (
        int(segments_with_speakers.loc[segments_with_speakers["speaker_cluster"] >= 0, "speaker_cluster"].max())
        if (segments_with_speakers["speaker_cluster"] >= 0).any()
        else -1
    )

    unknown_side_map["fallback_speaker_cluster"] = np.arange(
        max_cluster + 1,
        max_cluster + 1 + len(unknown_side_map),
    )

    unknown_side_map["fallback_speaker_cluster_id"] = unknown_side_map["fallback_speaker_cluster"].apply(
        lambda x: f"spk_unknown_side_{int(x):05d}"
    )

    segments_with_speakers = segments_with_speakers.merge(
        unknown_side_map,
        on=["call_id", "channel"],
        how="left",
    )

    mask = segments_with_speakers["is_unknown_speaker_cluster"]

    segments_with_speakers.loc[mask, "speaker_cluster"] = (
        segments_with_speakers.loc[mask, "fallback_speaker_cluster"].astype(int)
    )
    segments_with_speakers.loc[mask, "speaker_cluster_id"] = (
        segments_with_speakers.loc[mask, "fallback_speaker_cluster_id"]
    )

    segments_with_speakers = segments_with_speakers.drop(
        columns=["fallback_speaker_cluster", "fallback_speaker_cluster_id"]
    )

segments_with_speakers["has_speaker_cluster"] = True

# Candidate training rows.
