call_speaker = (
    segments_with_speakers[["call_id", "speaker_cluster_id"]]
    .drop_duplicates()
    .copy()
)

calls = sorted(call_speaker["call_id"].astype(str).unique())
speakers = sorted(call_speaker["speaker_cluster_id"].astype(str).unique())

call_to_idx = {c: i for i, c in enumerate(calls)}
speaker_to_idx = {s: len(calls) + i for i, s in enumerate(speakers)}

rows = []
cols = []

for r in call_speaker.itertuples(index=False):
    cidx = call_to_idx[str(r.call_id)]
    sidx = speaker_to_idx[str(r.speaker_cluster_id)]

    rows.extend([cidx, sidx])
    cols.extend([sidx, cidx])

n_nodes = len(calls) + len(speakers)
data = np.ones(len(rows), dtype=np.uint8)

graph = coo_matrix((data, (rows, cols)), shape=(n_nodes, n_nodes))

n_components, comp_labels = connected_components(
    graph,
    directed=False,
    return_labels=True,
)

call_split_groups = pd.DataFrame({
    "call_id": calls,
    "split_group_raw": comp_labels[:len(calls)],
})

# Renumber groups by size.
