import json
import re
import time
import requests
import pandas as pd
import numpy as np
from tqdm.auto import tqdm

OLLAMA_MODEL = "gemma4:31b"
OLLAMA_URL = "http://127.0.0.1:11434/api/chat"
OLLAMA_TAGS_URL = "http://127.0.0.1:11434/api/tags"

CALL_CHANNEL_LABEL_CSV = LABEL_OUT_DIR / "call_channel_gemma_role_stage.csv"
CALL_CHANNEL_LABEL_PARQUET = LABEL_OUT_DIR / "call_channel_gemma_role_stage.parquet"

CHECKPOINT_EVERY = 25

# Start tiny. Do not run 50 again until this works.
GEMMA_TEST_MODE = True
GEMMA_TEST_N = 5

# Speed controls. 7000 chars was too much.
TARGET_TRANSCRIPT_MAX_CHARS = 2500
OTHER_CONTEXT_MAX_CHARS = 900

ALLOWED_SPEAKER_ROLE = {"AGENT", "USER", "IVR", "MIXED", "UNKNOWN"}
ALLOWED_CALL_STAGE = {
    "ONBOARDING",
    "OFFBOARDING",
    "FOLLOW_UP",
    "ROUTINE_CHECKIN",
    "VOICEMAIL",
    "OTHER",
    "UNKNOWN",
}
ALLOWED_CONFIDENCE = {"high", "medium", "low"}


# ============================================================
# OLLAMA HEALTH CHECK
# ============================================================

try:
    tags_resp = requests.get(OLLAMA_TAGS_URL, timeout=20)
    tags_resp.raise_for_status()
    tags = tags_resp.json()

    available_models = [m.get("name", "") for m in tags.get("models", [])]
    print("Available Ollama models:", available_models)

    if OLLAMA_MODEL not in available_models:
        print("WARNING: OLLAMA_MODEL not found:", OLLAMA_MODEL)
        print("Set OLLAMA_MODEL to an exact available model name above.")

except Exception as e:
    raise RuntimeError(f"Ollama is not reachable at {OLLAMA_TAGS_URL}: {repr(e)}")


# ============================================================
# PROMPT
# ============================================================

CALL_CHANNEL_LABEL_SYSTEM = """
You classify one target channel transcript from a healthcare, support, or operations call dataset.

Classify only the target channel. Other-channel context is only background.

Allowed speaker_role values:
AGENT, USER, IVR, MIXED, UNKNOWN

Allowed call_stage values:
ONBOARDING, OFFBOARDING, FOLLOW_UP, ROUTINE_CHECKIN, VOICEMAIL, OTHER, UNKNOWN

Allowed confidence values:
high, medium, low

Rules:
- Be conservative.
- If the target transcript is a recorded menu, automated system, or machine prompt, use speaker_role=IVR.
- If the target transcript is an answering machine or voicemail greeting, use call_stage=VOICEMAIL.
- If the target sounds like an employee, nurse, coordinator, advisor, clinic/company caller, or support representative, use speaker_role=AGENT.
- If the target contains personal symptoms, personal answers, preferences, or requests from the receiver, use speaker_role=USER.
- Use MIXED only when clearly more than one speaker appears in the same target channel.
- Use UNKNOWN when evidence is weak.
- Do not infer medical facts not present in the transcript.
- Return JSON only. No markdown. No explanation outside JSON.

Required JSON schema:
{
  "speaker_role": "AGENT",
  "speaker_role_confidence": "high",
  "call_stage": "FOLLOW_UP",
  "call_stage_confidence": "medium",
  "reason": "short reason under 25 words"
}
""".strip()


# ============================================================
# HELPERS
# ============================================================

def trim_text_middle(text, max_chars):
    text = str(text or "").strip()

    if len(text) <= max_chars:
        return text

    head = max_chars // 2
    tail = max_chars - head

    return text[:head] + "\n[TRUNCATED]\n" + text[-tail:]


def extract_json_object(text):
    text = str(text or "").strip()

    # Remove markdown fences
    text = re.sub(r"^```(?:json)?\s*", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s*```$", "", text)

    try:
        return json.loads(text)
    except Exception:
        pass

    start = text.find("{")
    end = text.rfind("}")

    if start == -1 or end == -1 or end <= start:
        raise ValueError(f"No JSON object found. Raw output starts: {text[:500]}")

    candidate = text[start:end + 1]
    candidate = re.sub(r",\s*([}\]])", r"\1", candidate)

    return json.loads(candidate)


def clean_role(value):
    value = str(value or "").strip().upper()
    return value if value in ALLOWED_SPEAKER_ROLE else "UNKNOWN"


def clean_stage(value):
    value = str(value or "").strip().upper()
    return value if value in ALLOWED_CALL_STAGE else "UNKNOWN"


def clean_conf(value):
    value = str(value or "").strip().lower()
    return value if value in ALLOWED_CONFIDENCE else "low"


def normalize_label_obj(obj):
    return {
        "speaker_role": clean_role(obj.get("speaker_role")),
        "speaker_role_confidence": clean_conf(obj.get("speaker_role_confidence")),
        "call_stage": clean_stage(obj.get("call_stage")),
        "call_stage_confidence": clean_conf(obj.get("call_stage_confidence")),
        "reason": str(obj.get("reason", "")).strip()[:250],
    }


def ollama_chat_json(system_prompt, user_prompt, model=OLLAMA_MODEL, num_predict=140, timeout=240, retries=1):
    payload = {
        "model": model,
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_prompt},
        ],
        "stream": False,
        "format": "json",
        "options": {
            "temperature": 0,
            "num_predict": num_predict,
            "num_ctx": 4096,
        },
    }

    last_err = None
    last_raw = None

    for attempt in range(retries + 1):
        try:
            r = requests.post(OLLAMA_URL, json=payload, timeout=timeout)
            r.raise_for_status()

            data = r.json()
            content = data.get("message", {}).get("content", "")
            last_raw = content

            obj = extract_json_object(content)
            return normalize_label_obj(obj), content

        except Exception as e:
            last_err = e
            time.sleep(1.0 * (attempt + 1))

    raise RuntimeError(
        f"Ollama JSON labeling failed: {repr(last_err)} | raw={str(last_raw)[:500]}"
    )


def build_user_prompt_for_call_channel(row):
    transcript = trim_text_middle(
        row["call_channel_transcript"],
        TARGET_TRANSCRIPT_MAX_CHARS,
    )

    other_context = trim_text_middle(
        row.get("other_channel_context", ""),
        OTHER_CONTEXT_MAX_CHARS,
    )

    return f"""
Metadata:
call_id: {row["call_id"]}
target_channel: {row["channel"]}
speaker_cluster_id: {row.get("speaker_cluster_id", "")}
total_usable_speech_sec: {row.get("total_usable_speech_sec", "")}

Target channel transcript:
{transcript}

Other-channel context:
{other_context}
""".strip()


def label_one_call_channel(row):
    key = f'{row["call_id"]}__ch{row["channel"]}'

    transcript = str(row.get("call_channel_transcript", "") or "").strip()

    if not transcript:
        return {
            "call_id": row["call_id"],
            "channel": row["channel"],
            "call_channel_key": key,
            "speaker_role": "UNKNOWN",
            "speaker_role_confidence": "low",
            "call_stage": "UNKNOWN",
            "call_stage_confidence": "low",
            "label_reason": "empty transcript",
            "label_status": "empty_transcript",
        }

    user_prompt = build_user_prompt_for_call_channel(row)

    try:
        obj, raw = ollama_chat_json(
            CALL_CHANNEL_LABEL_SYSTEM,
            user_prompt,
            model=OLLAMA_MODEL,
            num_predict=140,
            timeout=240,
            retries=1,
        )

        return {
            "call_id": row["call_id"],
            "channel": row["channel"],
            "call_channel_key": key,
            "speaker_role": obj["speaker_role"],
            "speaker_role_confidence": obj["speaker_role_confidence"],
            "call_stage": obj["call_stage"],
            "call_stage_confidence": obj["call_stage_confidence"],
            "label_reason": obj["reason"],
            "label_status": "ok",
        }

    except Exception as e:
        return {
            "call_id": row["call_id"],
            "channel": row["channel"],
            "call_channel_key": key,
            "speaker_role": "UNKNOWN",
            "speaker_role_confidence": "low",
            "call_stage": "UNKNOWN",
            "call_stage_confidence": "low",
            "label_reason": repr(e)[:1000],
            "label_status": "error",
        }

