import json
import re
import time
import requests

NUM_PREDICT_LABEL = 512
OLLAMA_TIMEOUT = 300

def extract_json_object(text):
    text = str(text or "").strip()

    # Remove markdown fences
    text = text.replace("```json", "").replace("```", "").strip()
    text = re.sub(r"^json\s*", "", text, flags=re.IGNORECASE).strip()

    # 1. Direct JSON parse
    try:
        obj = json.loads(text)
        if isinstance(obj, dict):
            return obj
    except Exception:
        pass

    # 2. Extract from first { to last }
    start = text.find("{")
    end = text.rfind("}")

    if start != -1:
        candidate = text[start:end + 1] if end > start else text[start:]
        candidate = candidate.strip()
        candidate = re.sub(r",\s*([}\]])", r"\1", candidate)

        try:
            obj = json.loads(candidate)
            if isinstance(obj, dict):
                return obj
        except Exception:
            pass

        # 3. Salvage fields from incomplete JSON
        def field(name, default=""):
            m = re.search(rf'"{name}"\s*:\s*"([^"]*)"', candidate)
            return m.group(1).strip() if m else default

        role = field("speaker_role", "UNKNOWN")
        role_conf = field("speaker_role_confidence", "low")
        stage = field("call_stage", "UNKNOWN")
        stage_conf = field("call_stage_confidence", "low")
        reason = field("reason", "")

        if role != "UNKNOWN" or stage != "UNKNOWN":
            return {
                "speaker_role": role,
                "speaker_role_confidence": role_conf,
                "call_stage": stage,
                "call_stage_confidence": stage_conf,
                "reason": reason,
            }

    raise ValueError(f"No parseable label found. Raw output starts: {text[:500]}")


def clean_role(value):
    value = str(value or "").strip().upper()
    return value if value in ALLOWED_SPEAKER_ROLE else "UNKNOWN"


