print(str(debug_row["call_channel_transcript"])[:1000])

debug_prompt = build_user_prompt_for_call_channel(debug_row)

print("\nPROMPT CHARS:", len(debug_prompt))

t0 = time.time()

obj, raw = ollama_chat_json(
    CALL_CHANNEL_LABEL_SYSTEM,
    debug_prompt,
    model=OLLAMA_MODEL,
    num_predict=220,
    timeout=300,
    retries=1,
)

elapsed = time.time() - t0

print("elapsed sec:", elapsed)

print("\nRAW:")
print(str(raw)[:2000])

print("\nPARSED:")
print(obj)

# ============================================================
# GEMMA PREFLIGHT - 5 ROWS
# ============================================================

preflight_df = call_channel_df[
    call_channel_df["call_channel_transcript"].fillna("").astype(str).str.strip().ne("")
].copy()

preflight_df = preflight_df.sample(
    n=min(GEMMA_TEST_N, len(preflight_df)),
    random_state=42,
).reset_index(drop=True)

preflight_rows = []

for _, row in tqdm(preflight_df.iterrows(), total=len(preflight_df), desc="Gemma preflight"):
    preflight_rows.append(label_one_call_channel(row))

preflight_labels_df = pd.DataFrame(preflight_rows)

display(preflight_labels_df)

print("Preflight speaker_role:")
print(preflight_labels_df["speaker_role"].value_counts(dropna=False))

print("\nPreflight call_stage:")
print(preflight_labels_df["call_stage"].value_counts(dropna=False))

print("\nPreflight status:")
print(preflight_labels_df["label_status"].value_counts(dropna=False))

print("\nErrors:")
display(
    preflight_labels_df[
        preflight_labels_df["label_status"].eq("error")
    ][["call_id", "channel", "label_reason"]]
)

# ============================================================
# FULL PARALLEL GEMMA CALL + CHANNEL LABELING
# Resume-safe, checkpointed, ThreadPoolExecutor
# ============================================================

import os
import time
import json
import random
import threading
import pandas as pd
from pathlib import Path
from tqdm.auto import tqdm
from concurrent.futures import ThreadPoolExecutor, as_completed

# ----------------------------
# CONFIG
# ----------------------------

GEMMA_TEST_MODE = False

MAX_WORKERS = 8          # start 8. try 12/16 only if GPU/ollama stable
CHECKPOINT_EVERY = 250
REQUEST_STAGGER_SEC = 0.05

CALL_CHANNEL_LABEL_CSV = LABEL_OUT_DIR / "call_channel_gemma_role_stage_parallel.csv"
CALL_CHANNEL_LABEL_PARQUET = LABEL_OUT_DIR / "call_channel_gemma_role_stage_parallel.parquet"

FAILED_LABEL_CSV = LABEL_OUT_DIR / "call_channel_gemma_role_stage_parallel_failed.csv"

print("Output CSV:", CALL_CHANNEL_LABEL_CSV)
print("Output Parquet:", CALL_CHANNEL_LABEL_PARQUET)
print("MAX_WORKERS:", MAX_WORKERS)

# ----------------------------
# Prepare input
# ----------------------------

label_input_df = call_channel_df.copy()
label_input_df["call_id"] = label_input_df["call_id"].astype(str)
label_input_df["channel"] = label_input_df["channel"].astype(str)
label_input_df["call_channel_key"] = (
    label_input_df["call_id"] + "__ch" + label_input_df["channel"]
)

# Optional: skip empty transcripts
label_input_df["call_channel_transcript"] = (
    label_input_df["call_channel_transcript"]
    .fillna("")
    .astype(str)
    .str.strip()
)

print("Total call-channel rows:", len(label_input_df))
print("Non-empty transcripts:", label_input_df["call_channel_transcript"].ne("").sum())
print("Empty transcripts:", label_input_df["call_channel_transcript"].eq("").sum())

if GEMMA_TEST_MODE:
    label_input_df = label_input_df.head(100).copy()
    print("TEST MODE rows:", len(label_input_df))

# ----------------------------
# Resume existing labels
# ----------------------------

if CALL_CHANNEL_LABEL_CSV.exists() and CALL_CHANNEL_LABEL_CSV.stat().st_size > 0:
    done_df = pd.read_csv(CALL_CHANNEL_LABEL_CSV)
    done_df["call_id"] = done_df["call_id"].astype(str)
    done_df["channel"] = done_df["channel"].astype(str)

    if "call_channel_key" not in done_df.columns:
        done_df["call_channel_key"] = done_df["call_id"] + "__ch" + done_df["channel"]

    done_df = done_df.drop_duplicates("call_channel_key", keep="last")
    done_keys = set(done_df["call_channel_key"].astype(str))
    label_rows = done_df.to_dict("records")

    print("Resuming. Already done:", len(done_keys))
else:
    done_keys = set()
    label_rows = []
    print("Starting fresh.")

pending_df = label_input_df[
    ~label_input_df["call_channel_key"].isin(done_keys)
].copy()

print("Pending:", len(pending_df))

# ----------------------------
# Thread-safe checkpointing
# ----------------------------

lock = threading.Lock()
completed_since_save = 0
start_time = time.time()

def save_checkpoint(label_rows, suffix=""):
    if not label_rows:
        return

    out_df = pd.DataFrame(label_rows).drop_duplicates("call_channel_key", keep="last")

    tmp_csv = CALL_CHANNEL_LABEL_CSV.with_suffix(".csv.tmp")
    tmp_parquet = CALL_CHANNEL_LABEL_PARQUET.with_suffix(".parquet.tmp")

    out_df.to_csv(tmp_csv, index=False)
    out_df.to_parquet(tmp_parquet, index=False)

    tmp_csv.replace(CALL_CHANNEL_LABEL_CSV)
    tmp_parquet.replace(CALL_CHANNEL_LABEL_PARQUET)

    err_df = out_df[out_df["label_status"].eq("error")].copy()
    if len(err_df):
        err_df.to_csv(FAILED_LABEL_CSV, index=False)

    elapsed = time.time() - start_time
    rate = len(out_df) / max(elapsed, 1e-9)
    remaining = max(len(label_input_df) - len(out_df), 0)
    eta_hr = remaining / max(rate, 1e-9) / 3600

    print(
        f"checkpoint{suffix}: done={len(out_df)}, "
        f"rate={rate:.3f}/sec, eta_hr={eta_hr:.2f}, "
        f"errors={int((out_df['label_status'] == 'error').sum())}"
    )

# ----------------------------
# Worker
# ----------------------------

def label_worker(row_dict):
    # small stagger reduces simultaneous Ollama bursts
    time.sleep(random.random() * REQUEST_STAGGER_SEC)

    try:
        return label_one_call_channel(row_dict)
    except Exception as e:
        key = f'{row_dict["call_id"]}__ch{row_dict["channel"]}'
        return {
            "call_id": row_dict["call_id"],
            "channel": row_dict["channel"],
            "call_channel_key": key,
            "speaker_role": "UNKNOWN",
            "speaker_role_confidence": "low",
            "call_stage": "UNKNOWN",
            "call_stage_confidence": "low",
            "label_reason": repr(e)[:1000],
            "label_status": "error",
        }

# ----------------------------
# Run parallel labeling
# ----------------------------

records = pending_df.to_dict("records")

with ThreadPoolExecutor(max_workers=MAX_WORKERS) as ex:
    futures = [ex.submit(label_worker, r) for r in records]

    pbar = tqdm(as_completed(futures), total=len(futures), desc="Parallel Gemma labels")

    for fut in pbar:
        result = fut.result()

        with lock:
            key = result["call_channel_key"]

            if key not in done_keys:
                label_rows.append(result)
                done_keys.add(key)
                completed_since_save += 1

            done_count = len(done_keys)
            elapsed = time.time() - start_time
            rate = done_count / max(elapsed, 1e-9)
            remaining = max(len(label_input_df) - done_count, 0)
            eta_hr = remaining / max(rate, 1e-9) / 3600

            pbar.set_postfix({
                "done": done_count,
                "rate/s": round(rate, 3),
                "eta_hr": round(eta_hr, 2),
                "status": result.get("label_status", "")
            })

            if completed_since_save >= CHECKPOINT_EVERY:
                save_checkpoint(label_rows, suffix="")
                completed_since_save = 0

# Final save
save_checkpoint(label_rows, suffix=" final")

call_channel_labels_df = (
    pd.DataFrame(label_rows)
    .drop_duplicates("call_channel_key", keep="last")
)

print("\nFinal rows:", len(call_channel_labels_df))
print("\nStatus:")
print(call_channel_labels_df["label_status"].value_counts(dropna=False))

print("\nSpeaker role:")
print(call_channel_labels_df["speaker_role"].value_counts(dropna=False))

print("\nCall stage:")
print(call_channel_labels_df["call_stage"].value_counts(dropna=False))

display(call_channel_labels_df.head(20))



consensus_df = pd.read_parquet(
    MANIFESTS_DIR / "consensus_segments.parquet"
)

print(consensus_df.shape)
# display(consensus_df.head())

consensus_df.columns

