import pandas as pd
from pathlib import Path

cluster_cols = [
    "segment_id",
    "speaker_cluster_id",
    "speaker_cluster",
    "split_group_id",
    "speaker_assignment_confidence",
    "segment_to_side_centroid_sim",
]

available_cols = [c for c in cluster_cols if c in final_df.columns]

if "segment_id" not in consensus_df.columns:
    print("ERROR: segment_id missing in consensus_df")
else:
    if "segment_id" not in final_df.columns:
        print("ERROR: segment_id missing in final_df")
        consensus_df_new = consensus_df.copy()
    else:
        missing_cols = [c for c in cluster_cols if c not in final_df.columns]
        if missing_cols:
            print("WARNING: Missing columns in final_df:", missing_cols)

        final_merge_df = final_df[available_cols].copy()

        before_dedup = len(final_merge_df)
        final_merge_df = final_merge_df.drop_duplicates(subset=["segment_id"], keep="first")
        after_dedup = len(final_merge_df)

        if before_dedup != after_dedup:
            print(f"WARNING: Removed {before_dedup - after_dedup} duplicate segment_id rows from final_df")

        existing_overlap_cols = [
            c for c in available_cols
            if c != "segment_id" and c in consensus_df.columns
        ]

        if existing_overlap_cols:
            print("WARNING: These columns already exist in consensus_df and will be replaced:")
            print(existing_overlap_cols)
            consensus_base = consensus_df.drop(columns=existing_overlap_cols)
        else:
            consensus_base = consensus_df.copy()

        consensus_df_new = consensus_base.merge(
            final_merge_df,
            on="segment_id",
            how="left"
        )

        print("Old shape:", consensus_df.shape)
        print("New shape:", consensus_df_new.shape)

        added_cols = [c for c in available_cols if c != "segment_id"]

        print("\nMissing values in added columns:")
        print(consensus_df_new[added_cols].isna().sum())

        if consensus_df_new.shape[0] != consensus_df.shape[0]:
            print("WARNING: Row count changed. Check merge keys.")
        else:
            print("Row count OK")

        expected_cols = consensus_df.shape[1] + len([c for c in added_cols if c not in consensus_df.columns])
        print("Expected columns:", expected_cols)
        print("Actual columns:", consensus_df_new.shape[1])

display(consensus_df_new.head())

OUT_PATH = MANIFESTS_DIR / "consensus_segments_with_speaker_clusters.parquet"

try:
    consensus_df_new.to_parquet(OUT_PATH, index=False)
    print("Saved:", OUT_PATH)
    print("Final shape:", consensus_df_new.shape)
except Exception as e:
    print("Save failed:", repr(e))

